d(0,S,C,[], 'Der leere Beschreibungstext formuliert keine Leistung. Der benannte Mechanik-I-Lernbereich bündelt die sechs konkreten Ziele zu Dichte, Bewegung, Kräften und Reibung unter Jahrgang 10.', [], [], '')
d(1,P,'orientation', ['Persönliche Möglichkeiten von Physik in Alltag, Teilhabe, Studium und Beruf erkunden.'], 'Der Big-Picture-Einstieg ist ausdrücklich Relevanz und Orientierung und fordert keine fachliche Richtigkeitsprüfung. Das Erarbeiten des Curriculums ist der Motivationsrahmen; eine bewertete Physikbeherrschung darf daraus nicht abgeleitet werden.', [], [], 'Der Big-Picture-Einstieg')
d(2,P,B, ['Dichte von Festkörpern und Flüssigkeiten experimentell bestimmen.', 'Schweben, Schwimmen, Absinken und Aufsteigen aus Dichtevergleichen vorhersagen.'], 'Dichtemessung und die Vorhersage von Auftriebszuständen sind getrennt nachweisbare Leistungen. Die physikalische Stoffeigenschaft und das Verhalten im Medium sind die Ziele; Quotientenrechnung ist ein Mittel.', ['Masse-Volumen-Quotient und Dichtevergleich'], ['Dichtemessung versus Schwimmzustandsprognose'], 'Schweben und Schwimmen, Absinken und Aufsteigen')
d(3,P,N, ['Unter Anleitung einen Bewegungsversuch planen, durchführen und aus Weg-/Zeitmessungen mittlere Geschwindigkeitsbeträge bestimmen.'], 'Der gesamte Experimentablauf ist auf genau die mittlere Geschwindigkeit eines bewegten Körpers gerichtet. Planen und Messen liefern die Evidenz für diese bestimmte physikalische Größe.', ['Differenzen und Weg-Zeit-Quotient'], [], 'Beträge der mittleren Geschwindigkeiten')
d(4,P,B, ['Bewegungsdaten in geeigneten Darstellungen dokumentieren.', 'Ortsänderungen und Geschwindigkeiten einschließlich Momentangeschwindigkeit aus Darstellungen vergleichen.'], 'Die Erstellung einer Bewegungsdarstellung und deren Auswertung bis zur Momentangeschwindigkeit sind eigenständige Nachweise. Der Text legt weder Darstellungsart noch ein gemeinsames enges Vergleichskriterium fest.', ['Bewegungsdiagramme und lokale Änderungsraten'], ['Darstellungserstellung versus mittlerer und momentaner Bewegungsvergleich'], 'auch Momentangeschwindigkeit')
d(5,P,N, ['Aus identifizierten Kräften mit Superposition und Beharrung qualitativ die Änderung des Bewegungszustands vorhersagen.'], 'Kräfteidentifikation und Prinzipienauswahl dienen einer zusammenhängenden qualitativen Kraft-Wirkungs-Prognose. Es wird keine unabhängige abstrakte Vektoroperation geprüft.', ['Gegebenenfalls zeichnerische Kraftüberlagerung'], [], 'Superpositionsprinzip und/oder das Beharrungsprinzip')
d(6,P,B, ['Haft- und Gleitreibung messen und ihre Koeffizienten bestimmen.', 'Die Wirkung von Reibung bei technischen Bremsvorgängen begründet diskutieren.'], 'Die Mess- und Koeffizientenleistung kann ohne die technische Transferdiskussion gelingen. Zusätzlich bleibt die Unterscheidung von Haftgrenze und Gleitreibung als eigene fachliche Dimension sichtbar.', ['Kraftquotienten für Reibungskoeffizienten'], ['Haftreibung versus Gleitreibung; Koeffizientenbestimmung versus Bremsanwendung'], 'Gleitreibungs‑ und Haftzahlen')
d(7,P,N, ['An einer geneigten Ebene Kraftwirkungen mit sicherem Verhalten im Straßenverkehr begründet verbinden.'], 'Die Sicherheitsdiskussion ist hier direkt auf die physikalischen Kraftwirkungen eines engen Szenarios begrenzt. Der Text verlangt weder allgemeine Verkehrsrechtkenntnisse noch Motivation als Abschluss.', ['Gegebenenfalls Kräfteplan an der geneigten Ebene'], [], 'Kraftwirkungen an der geneigten Ebene')
d(8,S,C,[], 'Mechanik II ist ein Themenbündel ohne eigene Leistungsbeschreibung. Die fünf enthaltenen Ziele betreffen Hebel, Rollen, mechanische Energie und die Größen Kraft, Arbeit und Leistung.', [], [], '')
d(9,P,B, ['Gesetzmäßigkeiten ein- und zweiarmiger Hebel experimentell untersuchen.', 'Feste und lose Rollen sowie den Flaschenzug experimentell untersuchen und protokollieren.'], 'Mehrere unterschiedliche Maschinenprinzipien werden in einem Blatt zusammengefasst. Eine erfolgreiche Hebeluntersuchung weist die Rollen- und Flaschenzuggesetzmäßigkeiten nicht mit nach.', ['Kraft- und Wegverhältnisse; gegebenenfalls Drehmomente'], ['Hebelgesetz versus Rollen- und Flaschenzuggesetzmäßigkeiten'], 'ein‑ und zweiarmigen Hebeln, loser, fester Rolle und Flaschenzug')
d(10,P,N, ['Ein hebelbasiertes Gerät mit Drehpunkt und wirkenden Kräften analysieren und seine technische Funktion begründet bewerten.'], 'Identifikation, Hebelgesetz und Nutzenbewertung gehören zu einer Geräteanalyse desselben physikalischen Prinzips. Der Gerätekontext erweitert den Gegenstand nicht zu abstrakter Mathematik.', ['Hebelarm-Kraft-Verhältnisse'], [], 'mithilfe des Hebelgesetzes die Funktionsweise')
d(11,P,N, ['Einen mechanischen Vorgang als idealisierte Energieumwandlung fachsprachlich beschreiben.'], 'Die Beispiele aus Alltag, Technik und Natur variieren den Kontext einer einzigen Energieumwandlungsbeschreibung. Fachsprache ist das Qualitätskriterium derselben Leistung.', [], [], 'Energieumwandlungen bei mechanischen Vorgängen')
d(12,P,B, ['Ort oder Momentangeschwindigkeit mittels mechanischer Arbeits- und Energiebilanz bestimmen.', 'Reibungsverluste in die Energiebilanz realer Bewegungen einbeziehen.'], 'Die idealisierte Energiebilanz und die Bilanz mit dissipativer Arbeit verlangen unterschiedliche Modellentscheidungen. Die beliebigen Zeitpunkte benötigen zudem ein präziseres Bewegungsmodell als die Beschreibung nennt.', ['Energiegleichungen nach Ort oder Geschwindigkeit auflösen'], ['Idealisierte Bilanz versus Reibungsverluste; Zeit-Ort-Modell unbestimmt'], 'zu verschiedenen Zeitpunkten')
d(13,P,B, ['Kraft, Energie, Arbeit und Leistung über Bedeutung, Zusammenhänge und Einheiten fachsprachlich unterscheiden.', 'Zwischen Energie- und Arbeitseinheiten sicher umrechnen.'], 'Die Begriffsabgrenzung mehrerer Größen und die numerische Einheitenkonversion können unabhängig gelingen. Der Text bündelt die gesamte Größenlandkarte und eine eigene Rechenroutine.', ['Einheitenumrechnungen'], ['Viergrößen-Abgrenzung versus Einheitenkonversion'], 'Kraft, Energie, Arbeit und Leistung')
d(14,S,C,[], 'Der Elektrizitäts-Lernbereich in Jahrgang 10 enthält fünf Ziele von Stromkreisaufbau bis nachhaltiger Versorgung. Die leere Beschreibung ist kein eigener prüfbarer Stromkreisinhalt.', [], [], '')
d(15,P,B, ['Bauteile und Funktionen eines Stromkreises fachgerecht erklären.', 'Elektrische Stromkreisvorgänge mithilfe mechanischer Analogien veranschaulichen.'], 'Funktionale Bauteilkenntnis und das begrenzte Übertragen einer Analogie sind eigene Leistungen. Das Blatt benennt keinen einzelnen Bauteil oder eng begrenzten Stromkreisvorgang.', [], ['Stromkreisbauteile versus mechanische Modellanalogie'], 'mithilfe mechanischer Analogien')
d(16,P,B, ['Zwischen Schaltplan und realem Aufbau übertragen.', 'Mit sachgerecht eingesetzten Volt- und Amperemetern Widerstände aus eigenen Messungen bestimmen.', 'Das Gefahrenpotenzial der gemessenen Strom- und Spannungswerte abwägen.'], 'Darstellungswechsel, Messanordnung/Widerstandsbestimmung und elektrische Sicherheit sind getrennte Erfolgskriterien. Ein korrekt gezeichneter Plan beweist keine sichere Messgeräteverwendung.', ['U-I-Quotient zur Widerstandsbestimmung'], ['Schaltplantranslation versus Messkompetenz versus Gefahrenabwägung'], 'wägen das Gefahrenpotenzial')
d(17,P,B, ['Widerstandsschaltungen planen und aufbauen.', 'Strom, Spannung, Leistung und Widerstand in der Schaltung bestimmen.', 'Haushaltsnetze oder Mehrfachsteckdosen hinsichtlich sicherer Dimensionierung abschätzen.'], 'Die Beschreibung verbindet praktische Schaltungskonstruktion, mehrere physikalische Berechnungen und die Übertragung auf Haushaltslasten. Die Leistungs- und Sicherheitsdimension ist nicht durch eine Widerstandsberechnung abgedeckt.', ['Schaltungs- und Leistungsgleichungen; Größenordnungsabschätzung'], ['Schaltungsaufbau versus elektrische Größenbilanz versus Haushaltsdimensionierung'], 'erforderliche Dimensionierung abzuschätzen')
d(18,P,N, ['Energieumwandlungen und Stromwirkungen eines elektrischen Geräts unter Einbeziehung seines Wirkungsgrads erklären.'], 'Die Stromwirkung und der Wirkungsgrad werden zur selben Geräte-Energiebilanz zusammengeführt. Die wechselnden Geräte sind Anwendungsfälle einer physikalischen Erklärung.', ['Verhältnis nutzbarer zu zugeführter Energie'], [], 'auch unter Berücksichtigung des Wirkungsgrades')
d(19,I,B, ['Wege elektrischer Energieversorgung physikalisch vergleichen.', 'Eine Nachhaltigkeitsposition zu diesen Wegen mit begründeten Kriterien vertreten.'], 'Nachhaltigkeit enthält neben der physikalischen Versorgungsfunktion eine eigenständige gesellschaftliche Bewertung. Weder Kriterien noch Vergleichsscope sind im sehr offenen Argumentationsauftrag festgelegt.', [], ['Physikalischer Versorgungsvergleich versus Nachhaltigkeitsurteil; Kriterien und Vergleichsscope offen'], 'nachhaltigen elektrischen Energieversorgung')
d(20,S,C,[], 'Der Wärmelehre-Lernbereich unter Jahrgang 10 bündelt acht Ziele zu Teilchenmodell, Temperatur, Wärmekapazität, Phasenübergängen und Transport. Er besitzt keine eigene Leistungsbeschreibung.', [], [], '')
d(21,P,N, ['Aggregatzustände mit demselben Teilchenmodell für ein Alltagsphänomen erklären.'], 'Fest, flüssig und gasförmig sind die kontrastierten Zustände innerhalb einer Modellkompetenz. Es werden keine unabhängigen chemischen Stoffreaktionen oder biologischen Prozesse gefordert.', [], [], 'Aggregatzustände fest, flüssig und gasförmig')
d(22,P,B, ['Thermische Längenausdehnung experimentell als quantitatives Gesetz bestimmen und anwenden.', 'Thermische Volumenausdehnung experimentell als quantitatives Gesetz bestimmen und anwenden.'], 'Längen- und Volumenänderungen von Festkörpern und Flüssigkeiten verlangen verschiedene Messungen und Modellgrößen. Eine bestimmte Längenausdehnung deckt das Flüssigkeitsvolumen nicht automatisch ab.', ['Ausdehnungskoeffizienten aus Messwerten; proportionale Modelle'], ['Längenausdehnung versus Volumenausdehnung mit unterschiedlichen Stoff-/Geometriescopes'], 'Längen‑ und Volumenänderung')
d(23,P,N, ['Ein Ausdehnungsthermometer erklären und für eine konkrete Temperaturmessung passend auswählen.'], 'Die Gerätewahl prüft die Anwendung desselben Ausdehnungsprinzips unter Messbedingungen. Eine eigene allgemeine Gerätekunde wird nicht verlangt.', [], [], 'wählen zur Temperaturmessung in Experimenten geeignete Geräte')
d(24,P,N, ['Den absoluten Temperaturnullpunkt im Teilchenmodell begründen und daraus die Kelvin-Skala erklären.'], 'Nullpunktbegründung und Skalenableitung bilden eine einzige physikalische Begründungskette. Die Skala ist keine unabhängige Mathematikkompetenz.', ['Temperatur-Skalenbezug'], [], 'Temperaturskala nach Kelvin')
d(25,P,N, ['Spezifische Wärmekapazität aus Daten zu Wärmezufuhr und Temperaturänderung bestimmen.'], 'Die Datenauswertung zielt ausdrücklich auf eine bestimmte Stoffgröße. Festkörper und Flüssigkeiten sind Varianten dieses Messziels.', ['Proportionalitätsauswertung von Q, m und Temperaturänderung'], [], 'spezifische Wärmekapazität')
d(26,P,N, ['Eine experimentelle Mischtemperatur bei gleicher spezifischer Wärmekapazität mit der Mischungsregel überprüfen.'], 'Messung und Modellvergleich untersuchen dieselbe begrenzte Mischsituation. Der Geltungsbereich gleicher spezifischer Wärmekapazität macht die Leistung hinreichend eng.', ['Gewichtete Temperaturbilanz'], [], 'gleicher spezifischer Wärmekapazität')
d(27,P,B, ['Phasenübergänge im Teilchenmodell erklären.', 'Schmelz- und Verdampfungswärme in einer quantitativen Latentwärmebilanz anwenden.'], 'Die mikroskopische Übergangserklärung und die quantitative gespeicherte/entzogene Wärme sind eigenständige Lernleistungen. Schmelzen und Verdampfen sowie Speicher und Kühlakku erweitern den Scope weiter.', ['Wärmemenge aus Masse und spezifischer Übergangswärme'], ['Teilchenmodell des Übergangs versus quantitative Latentwärmebilanz'], 'Schmelz‑ und Verdampfungswärme')
d(28,P,B, ['Wärmeleitung und Wärmestrahlung mit passenden einfachen Modellen beschreiben.', 'Konvektion über temperaturbedingte Dichteunterschiede begründen und Gewässerschichtung erklären.'], 'Drei physikalisch unterschiedliche Transportmechanismen werden zusammen mit einer ökologischen Anwendung gebündelt. Eine Konvektionserklärung weist Strahlungs- und Leitungsmodelle nicht nach.', [], ['Wärmeleitung versus Strahlung versus dichtegetriebene Konvektion'], 'jahreszeitlich unterschiedlichen Temperaturschichtungen')
d(29,S,C,[], 'Optik in Jahrgang 10 ordnet fünf eigenständige Ziele zu Schatten, Reflexion/Brechung, Linsen, Geräten und Sehen. Der Zeitumfang und Lernbereichstitel sind Strukturmetadaten.', [], [], '')
d(30,P,B, ['Schatten und Finsternisse mithilfe konstruierter Lichtstrahlen erklären.', 'Mondphasen geometrisch aus Beleuchtung und Blickrichtung erklären.'], 'Schattenwurf/Finsternis und die sichtbare beleuchtete Mondfläche sind verschiedene Ursachen. Gerade die Bündelung der Mondphasen mit Schatten birgt eine eigene Verwechslungsgefahr.', ['Strahlenkonstruktion und räumliche Beleuchtungsgeometrie'], ['Schatten/Finsternis versus Mondphasen-Beleuchtungsgeometrie'], 'Sonnen‑ und Mondfinsternissen sowie der Mondphasen')
d(31,P,B, ['Reflexion und Brechung experimentell untersuchen.', 'Brechungsindex und Totalreflexionsgrenzwinkel aus Messungen bestimmen und Lichtleitung erklären.'], 'Reflexionsgesetz und Brechung/Totalreflexion sind unabhängig assessierbare Inhalte. Die Lichtleiteranwendung setzt die Grenzwinkeluntersuchung voraus, ersetzt aber keine Reflexionsmessung.', ['Winkelmessung und gegebenenfalls trigonometrische Brechungsbeziehung'], ['Reflexion versus Brechungsindex versus Totalreflexionsbedingung'], 'Brechungsindex und den Grenzwinkel')
d(32,P,B, ['Strahlengänge und Bildgrößen/-weiten einer Sammellinse konstruieren und experimentell überprüfen.', 'Bildentstehung im Auge sowie Kurz- und Weitsichtigkeit erklären.'], 'Die Linsenabbildung und die Modellierung zweier Sehfehler können getrennt verstanden oder verfehlt werden. Die Augenanwendung geht über die Überprüfung eines konstruierten Linsenbilds hinaus.', ['Geometrische Strahlenkonstruktion; Bildmaßstab'], ['Sammellinsenabbildung versus Augenmodell und Sehfehler'], 'Kurz‑ und Weitsichtigkeit als Sehfehler')
d(33,I,B, ['Optische Geräte zu einer konkreten Problemfrage quellenbasiert untersuchen.', 'Ihre historische Einordnung und heutige Alltagsbedeutung fachsprachlich präsentieren.'], 'Gerätephysik, historische Einordnung und Bedeutung werden in einem offenen Rechercheauftrag verbunden. Ohne benannte Problemfrage ist der Zielumfang nicht auf ein Gerät oder eine Funktionskompetenz eingegrenzt.', [], ['Gerätefunktion versus historische Einordnung versus Alltagsbedeutung; Rechercheproblem offen'], 'deren geschichtliche Einordnung')
d(34,P,N, ['Sehen als Empfang direkten oder gestreuten Lichts von primären oder sekundären Lichtquellen erklären.'], 'Die Lichtquellenunterscheidung dient einer einzigen konsistenten Erklärung des Sehvorgangs. Eine separate Augenphysiologie ist nicht beschrieben.', [], [], 'direkten oder gestreuten Lichteinfall')
d(35,S,Y,[], 'Der Jahrgang-10-Knoten besitzt einen leeren Beschreibungstext und enthält die fünf Ph10-Lernbereiche. Er ist eine Jahrgangsplatzierung, kein fachlicher Leistungsnachweis.', [], [], '')
d(36,S,C,[], 'Der ABU11-Lernbereich Geradlinige Bewegung enthält vier verschiedene kinematische Ziele. Seine Stundenangabe und Profilschreibweise strukturieren den Unterricht ohne eigene assessierbare Aussage.', [], [], '')
d(37,P,N, ['An geradlinigen Stroboskopbildern mit gewähltem Bezugssystem mittlere und angenäherte momentane Geschwindigkeiten aus Ort und Zeitauflösung bestimmen.'], 'Ortserfassung und Zeitauflösungsvergleich bilden einen eng gefassten Stroboskop-Auswertungsauftrag. Die Methode bleibt an die physikalische Geschwindigkeit gebunden.', ['Ortsdifferenzen, Zeitintervalle und Änderungsquotienten'], [], 'unterschiedlicher Zeitauflösungen der Bilder')
d(38,P,B, ['Gleichförmige lineare Bewegung experimentell als Zusammenhang kinematischer Größen bestätigen.', 'Gleichmäßig beschleunigte Bewegung experimentell auswerten und gegebenenfalls zur Proportionalität transformieren.'], 'Konstante Geschwindigkeit und konstante Beschleunigung haben verschiedene Gesetzmäßigkeiten. Der gemeinsame Experimentablauf macht diese beiden Inhaltsziele nicht zu einer einzigen Kompetenz.', ['Tabellen, Diagramme, Wertetransformation zu direkter Proportionalität'], ['Gleichförmige versus gleichmäßig beschleunigte Bewegung; Transformationsentscheidung offen'], 'gleichförmigen und gleichmäßig beschleunigten')
d(39,P,B, ['Alltagsbewegungen aus Diagrammen interpretieren.', 'Mit Koordinatengleichungen berechnen und das Ergebnis für vorausschauendes ressourcenschonendes Verkehrsverhalten verwenden.'], 'Diagramminterpretation und quantitative Koordinatenmodellierung sind unterschiedliche Nachweise. Der zusätzliche Verkehrsauftrag benennt keine begrenzte Situation oder gemeinsame Entscheidungsgröße.', ['Bewegungsdiagramme; kinematische Koordinatengleichungen'], ['Diagrammdeutung versus Koordinatenrechnung versus Verkehrsentscheidung'], 'ressourcenschonendes und umweltbewusstes Verhalten')
d(40,P,B, ['Weg aus der Fläche im Zeit-Geschwindigkeits-Diagramm abschätzen und deuten.', 'Geschwindigkeitsänderung aus der Fläche im Zeit-Beschleunigungs-Diagramm abschätzen und eine Verkehrssituation beurteilen.'], 'Zwei Flächenbedeutungen mit unterschiedlichen Einheiten und Bewegungsgrößen sind unabhängig assessierbar. Geometrische Fläche ist hier die Darstellungsmethode, nicht das fachliche Ziel.', ['Graphflächenabschätzung'], ['Fläche als Weg versus Fläche als Geschwindigkeitsänderung'], 'zurückgelegten Weg bzw. die Geschwindigkeitsänderung')
d(41,S,C,[], 'Der ABU11-Dynamikcluster bündelt Newton-Anwendung, F-m-a-Berechnung und Reibung auf der geneigten Ebene. Er enthält drei Ziele und keine eigene fachliche Beschreibung.', [], [], '')
d(42,P,N, ['Mit Kräfteplänen und Newtonschen Gesetzen qualitativ die Änderung eines alltagsnahen Bewegungszustands vorhersagen.'], 'Der Kräfteplan liefert die resultierende Kraft für dieselbe qualitative Prognose. Die Aufzugfahrt ist ein enger beispielhafter Kontext dieser dynamischen Modellierung.', ['Zeichnerische Kräfteaddition'], [], 'zeichnerische Strategien mithilfe von Kräfteplänen')
d(43,P,N, ['Mit Kraft, Masse und Beschleunigung die Wirkung eines stoßdämpfenden Personenschutzes beurteilen.'], 'Die Berechnung dient derselben dynamischen Schutzwirkung; Knautschzone, Dämpfer und Helm sind Kontextvarianten. Das Blatt fordert keine unabhängige medizinische Diagnose.', ['Umstellen des F-m-a-Zusammenhangs'], [], 'Knautschzonen, Aufpralldämpfern')
d(44,P,N, ['Eine reibungsfreie oder reibungsbehaftete Bewegung eines Fahrzeugs auf einer geneigten Ebene physikalisch vorhersagen.'], 'Der Vergleich mit und ohne Reibung ist eine Modellvariante derselben eindimensionalen Kraftbilanz. Genauere Szenariobegrenzung ist für Aufgaben nötig, aber der Inhalt bleibt eine dynamische Prognose.', ['Kräftezerlegung und Bewegungszusammenhang'], [], 'Fahrzeugen entlang einer geneigten Ebene')
d(45,S,C,[], 'Der ABU11-Kreisbewegungs-Lernbereich ordnet vier Ziele zu Kinematik, radialen Kräften, Kurvenverkehr und rotierenden Maschinen. Der Knoten selbst beschreibt keine individuelle Leistung.', [], [], '')
d(46,P,B, ['Drehbewegungen als gleichförmige Kreisbewegung modellieren und kinematisch quantifizieren.', 'Die Dynamik durch Zentripetalbeschleunigung und Zentripetalkraft erklären.'], 'Kinematische Kreisgrößen und die verursachende Radialkraft sind eigenständige Inhalte. Die Kenntnis von Umlaufdauer und Frequenz beweist kein Verständnis der Kraftdynamik.', ['Kreisgeometrie und Beziehungen zwischen Winkel- und Bahngrößen'], ['Kreisbewegungskinematik versus Zentripetaldynamik'], 'Umlaufdauer, Frequenz, Bahnradius, Drehwinkel')
d(47,P,N, ['Die Abhängigkeit radialer Beschleunigung und Kraft von Winkelgeschwindigkeit und Radius aus Messreihen mit Newton erklären.'], 'Beschleunigung und Kraft werden durch Newton zu derselben radialen Gesetzmäßigkeit verbunden. Die mathematische Formulierung ist Evidenz der physikalischen Auswertung.', ['Messreihenanalyse und quadratische/proportionale Zusammenhänge'], [], 'Radialbeschleunigung, Radialkraft, Winkelgeschwindigkeit und Radius')
d(48,P,N, ['Eine Kurvenfahrt als Kreisbewegung mit resultierender Zentripetalkraft analysieren und daraus eine Geschwindigkeitsbegrenzung beurteilen.'], 'Kräfteidentifikation, Berechnung und Verkehrsbeurteilung gehören zu einer konkreten dynamischen Kurvenentscheidung. Eine unabhängige politische Begründung von Tempolimits steht nicht im Text.', ['Kräfteaddition und Kreisbewegungsgleichungen'], [], 'Notwendigkeit von Geschwindigkeitsbegrenzungen')
d(49,P,N, ['Schutzeinrichtungen und zulässige Höchstdrehzahlen aus den physikalischen Risiken rotierender Maschinenteile erklären.'], 'Der Text fordert eine begrenzte physikalische Sicherheitsbegründung für Rotation. Seine Bedeutungsaussage ist fachlicher Transfer und kein motivationsbezogener Orientierungsabschluss.', [], [], 'Angabe von Höchstdrehzahlen')
d(50,S,C,[], 'Der ABU11-Energiecluster enthält vier Ziele zu Energieformen, Arbeit aus Diagrammen, Alltagsberechnung und effizienter Nutzung. Die leere Beschreibung ist ein Themenrahmen.', [], [], '')
d(51,P,N, ['Mechanische Energieumwandlungen in einer Alltagssituation fachsprachlich beschreiben und von Alltagsbegriffen abgrenzen.'], 'Beschreibung und Sprachabgrenzung prüfen dieselbe physikalische Energieumwandlung. Die Liste unterschiedlicher Energieformen ist Teil dieser einen Bilanzperspektive.', [], [], 'unterschiedlichen Formen mechanischer Energie')
d(52,P,N, ['Mechanische Arbeit aus der Fläche eines gegebenen Weg-Kraft-Diagramms auch für veränderliche Kräfte bestimmen.'], 'Die geometrische Auswertung hat genau einen physikalischen Endwert: verrichtete Arbeit. Feder und Luftwiderstand sind mögliche Kraftverläufe für denselben Auftrag.', ['Elementare geometrische Graphflächenbestimmung'], [], 'nicht konstante Kräfte entlang eines Weges')
d(53,P,B, ['Alltagsprozesse mit mechanischer Arbeit, Energie und Energieerhaltung quantitativ lösen.', 'Leistung und Wirkungsgrad in die Prozessbewertung einbeziehen und Einheiten konsistent umrechnen.'], 'Der offene Problemlöseauftrag bündelt Energie-, Kraft-, Leistungs- und Effizienzbeziehungen. Ein Erfolg bei einer Energiebilanz sichert die unabhängige Leistung/Wirkungsgrad-Dimension nicht.', ['Mehrere physikalische Größengleichungen und Einheitenkonversion'], ['Energiebilanz versus Leistung/Wirkungsgrad; Problemlösescope offen'], 'Kraft, Energie, Arbeit und Leistung auch unter Einbeziehung des Wirkungsgrades')
d(54,I,B, ['Energietransport und Umwandlung mit Arbeit, Energie, Leistung und Wirkungsgrad quantitativ erklären.', 'Die Bedeutung effizienter Energienutzung für Mensch und Umwelt begründet einschätzen.'], 'Die technische Energierechnung und die ökologische/gesellschaftliche Einschätzung brauchen unterschiedliche Evidenz. Die Beschreibung begrenzt diese Bedeutungsbewertung nicht auf ein rein physikalisches Kriterium.', ['Energie-, Leistungs- und Wirkungsgradrechnung'], ['Technische Energiebilanz versus menschlich-ökologische Nutzenbewertung'], 'für Mensch und Umwelt')
d(55,S,C,[], 'Der T11-Bewegungscluster bündelt fünf Ziele vom krummlinigen Stroboskopbild bis zum schiefen Wurf. Der Titel und Zeitumfang sind Themenorganisation, kein eigener Zieltext.', [], [], '')
d(56,P,N, ['Krummlinige Bewegung aus Stroboskopbildern in einem Bezugssystem als mittlere und angenäherte momentane Geschwindigkeitsvektoren auswerten.'], 'Betrag und Richtung gehören zur einen physikalischen Vektorgröße Geschwindigkeit. Die Zeitauflösung und Ortsmessung sind dafür benötigte Beobachtungsverfahren.', ['Ortsvektordifferenzen und Zeitquotienten'], [], 'Betrag und Richtung mittlerer und momentaner Geschwindigkeiten')
d(57,P,B, ['Gleichförmige lineare Bewegungen experimentell modellieren.', 'Beschleunigte lineare Bewegungen experimentell modellieren und Daten zur direkten Proportionalität transformieren.'], 'Im T11-Text sind beschleunigte Bewegungen sogar ohne Einschränkung auf konstante Beschleunigung benannt. Das Feld mehrerer Bewegungsmodelle und Transformationen bleibt deutlich breiter als eine Einzelkompetenz.', ['Messdatentabellen, Diagramme und Wertetransformation'], ['Gleichförmiges versus beschleunigtes Modell; Beschleunigungsverlauf offen'], 'gleichförmigen und beschleunigten linearen Bewegungen')
d(58,P,B, ['Zeit-Ort-, Zeit-Geschwindigkeits- und Zeit-Beschleunigungs-Diagramme erstellen und miteinander verknüpfen.', 'Mittlere und momentane Bewegungsgrößen aus Steigungen bestimmen.', 'Orts- und Geschwindigkeitsänderungen aus Flächen bestimmen.'], 'Drei Diagrammarten, Erstellung und Deutung sowie Steigungs- und Flächenoperationen bei nichtkonstanter Beschleunigung bilden mehrere eigenständige Inhaltseinheiten. Alle zielen auf Bewegung, nicht auf abstrakte Analysisbeherrschung.', ['Geometrische und analytische Steigungs- und Flächenverfahren'], ['Drei Diagrammarten; Ableitungsdeutung versus Flächendeutung; nichtkonstante Beschleunigung'], 'nicht konstanter Beschleunigung')
d(59,P,N, ['Eine geradlinige Alltagssituation mit linearem oder quadratischem Bewegungsmodell samt physikalischen Parametern und Gültigkeitsbereich beurteilen.'], 'Funktionswahl, Parameteraussage und Bereich gehören zu einer zusammenhängenden Bewegungsmodellierung. Die Verkehrsbeurteilung verwendet die daraus bestimmten Größen desselben Modells.', ['Lineare und quadratische Funktionen; Parameter- und Bereichsbestimmung'], [], 'sinnvollen Gültigkeitsbereich ihrer Modellierung')
d(60,P,N, ['Einen schiefen Wurf im gewählten Bezugssystem vektoriell prognostizieren und die Sportbewegung mit Videoanalyse überprüfen.'], 'Koordinatenwahl, Prognose und empirische Kontrolle sind auf ein bestimmtes Wurfmodell begrenzt. Die Vektoren und Gleichungen sind Werkzeuge der physikalischen Bewegungsprognose.', ['Vektoren, Koordinatengleichungen und Videoauswertung'], [], 'auf einen schiefen Wurf')
d(61,S,C,[], 'T11 Dynamik enthält vier Leistungsblätter zur experimentellen Kraftwirkung, Newton-Kräfteplänen, geneigter Ebene/Atwood und Stößen. Der leere Text lässt den Lernbereich als Bündel bestehen.', [], [], '')
d(62,P,N, ['Die durch eine Kraft verursachte Geschwindigkeitsänderung prognostizieren, experimentell überprüfen und in passenden Darstellungen belegen.'], 'Der eigene Versuch und die drei Ausdrucksformen stützen dieselbe Kraft-Geschwindigkeits-Prognose. Ihr Wechsel ist kein zusätzlicher unabhängiger Inhaltsgegenstand.', ['Grafische und mathematische Darstellung der Messwerte'], [], 'Änderung der Geschwindigkeit eines Körpers durch eine Kraftwirkung')
d(63,P,N, ['Die Bewegungsauswirkung einer resultierenden Kraft mithilfe Newtonscher Gesetze und rechnerischer/zeichnerischer Kräftepläne vorhersagen.'], 'Rechnen und Zeichnen sind komplementäre Wege zum selben Kraftmodell in einer Alltagssituation. Eine separate reine Vektorrechnung wird nicht als Lerngegenstand formuliert.', ['Rechnerische und zeichnerische Kraftresultante'], [], 'rechnerische und zeichnerische Strategien')
d(64,P,B, ['Bergauf- und Bergabbewegung mit und ohne eigenen Antrieb einschließlich Reibung prognostizieren.', 'Die gekoppelte Bewegung einer Atwoodschen Fallmaschine prognostizieren.'], 'Das gekoppelte Zweikörpersystem erfordert eine andere Systemwahl und Seilbedingung als ein Fahrzeug auf der Ebene. Mehrere Antriebs- und Reibungsfälle sind zusätzlich gebündelt.', ['Kräftezerlegung und gekoppelte Bewegungsgleichungen'], ['Ein-Körper-Schräge versus gekoppeltes Atwood-System; Antriebs-/Reibungsfälle'], "Atwood'sche Fallmaschine")
d(65,P,B, ['Kraftwirkung und Impulsänderung beim eindimensionalen Stoß zeichnerisch und rechnerisch analysieren.', 'Impulsänderungen bei zweidimensionalen Stößen zeichnerisch bestimmen und Fahrzeugfolgen diskutieren.'], 'Ein- und zweidimensionale Stoßmodelle unterscheiden sich in Richtungskomponenten und zulässigen Auswertewegen. Wechselwirkung, Stoßrechnung und Beschleunigungsfolgen sind nicht durch einen einzigen Rechennachweis gedeckt.', ['Impulsvektorkonstruktion und eindimensionale Impulsrechnung'], ['Eindimensionaler versus zweidimensionaler Stoß; Impulsänderung versus Beschleunigungsfolge'], 'ein‑ und zweidimensionalen Stoßvorgängen')
d(66,S,C,[], 'T11 Energie und Arbeit ist ein Cluster aus drei Zielen zu Energiebilanz, Arbeit aus Kraftgraphen und kombinierter Erhaltungsanalyse. Er enthält selbst keinen assessierbaren Satz.', [], [], '')
d(67,P,N, ['Mechanische Energieumwandlungen mit einbezogener Arbeit qualitativ darstellen und als quantitative Energieerhaltung zur Bewegungsprognose nutzen.'], 'Die Darstellungen und quantitative Rechnung gehen in derselben Arbeits-Energiebilanz auf. Stabhochsprung und Speedski sind mögliche Situationen für die eine Bilanzkompetenz.', ['Grafische Energiebilanz und Energiegrobgleichungen'], [], 'Höhe eines Stabhochsprungs')
d(68,P,N, ['Arbeit bei einem veränderlichen Kraftverlauf aus der geometrischen Fläche im gegebenen Weg-Kraft-Diagramm abschätzen.'], 'Die Vorgabe eines Diagramms und die eine physikalische Zielgröße begrenzen den Inhalt. Die Flächengeometrie ist eine Methode für die Arbeitsschätzung.', ['Elementare Flächenzerlegung und Abschätzung'], [], 'die zu verrichtende Arbeit abzuschätzen')
d(69,P,B, ['Eine Loopingbewegung mit Energieerhaltung und Kraftdynamik analysieren.', 'Einen zentralen Stoß mit Impuls- und Energiebilanz analysieren und fachsprachlich präsentieren.'], 'Looping und zentraler Zusammenstoß verlangen unterschiedliche physikalische System- und Erhaltungsentscheidungen. Die offene Kombination dreier Konzepte ist ein breiter Transferrahmen.', ['Verknüpfte Energie-, Impuls- und Kraftgleichungen'], ['Energie/Kraft beim Looping versus Energie/Impuls beim Stoß'], 'Loopingfahrt, zentraler Zusammenstoß')
d(70,S,C,[], 'Das T11-Praktikum bündelt sieben experimentelle Auswerte-, Planungs-, Dokumentations- und Videoleistungen. Es ist ein Themencluster mit Zeitumfang, keine Kompetenzachse oder einzelne Durchführungskompetenz.', [], [], '')
d(71,P,N, ['Aus einer physikalischen Messreihe mit geeigneter grafischer Transformation ein Gesetz samt physikalisch gedeuteter Proportionalitätskonstante ableiten.'], 'Datenlinearisierung und Konstantendeutung sind Bestandteile einer einzigen empirischen Gesetzesgewinnung. Die zugrunde liegende Theorie hält die mathematische Gerade an den physikalischen Gegenstand gebunden.', ['Koordinatentransformation, Ausgleichsgerade und Steigungsbestimmung'], [], 'physikalische Bedeutung der Proportionalitätskonstante')
d(72,P,B, ['Vorgegebene physikalische Experimente mit analogen oder digitalen Geräten selbständig durchführen und auswerten.', 'Die zugrunde liegenden Theorien aus Texten erschließen.'], 'Es werden weder ein Versuchstyp noch ein physikalisches Gesetz festgelegt. Textbasierte Theorieerschließung und praktische Durchführung sind eigenständige methodische Leistungsdimensionen.', ['Experimentspezifische Datenauswertung nicht festgelegt'], ['Experiment-/Theoriescope offen; Textverständnis versus Versuchsdurchführung'], 'Studium von Texten auf verschiedenem Anspruchsniveau')
d(73,P,B, ['Einen eigenen Versuchsaufbau für eine physikalische Problemstellung entwickeln und seine Verallgemeinerbarkeit prüfen.', 'Systematische Messfehler qualitativ bewerten und Größtfehler grob abschätzen.'], 'Versuchskonstruktion und Fehlerbewertung sind getrennt prüfbare methodische Kompetenzen. Die ausdrücklich begrenzte Fehlerrechnung darf nicht zur allgemeinen mathematischen Statistik erweitert werden.', ['Grobe Größtfehlerabschätzung ohne intensive Fehlerrechnung'], ['Versuchskonstruktion/Validität versus systematischer Fehler und Größtfehler'], 'ohne intensive Fehlerrechnung')
d(74,P,N, ['Eine physikalische Messreihe digital erfassen, grafisch darstellen und anhand einer theoriegebundenen Regressionskurve auswerten.'], 'Die Geräte- und Programmauswahl stützen eine zusammenhängende softwarebasierte physikalische Auswertung. Regression ist hier kein freistehender mathematischer Zielinhalt.', ['Softwareunterstützte Regressionskurven'], [], 'softwareunterstützte Einpassen von Regressionskurven')
d(75,P,N, ['Ein physikalisches Versuchsprotokoll mit Aufbau, Messwerten, Auswertung und Schlussfolgerung formal und fachsprachlich korrekt verfassen.'], 'Die vier Protokollteile sind Qualitätsbestandteile eines einzelnen Dokumentationsprodukts. Der Text bezeichnet keine bloße Administration, sondern eine prüfbare fachliche Kommunikationsleistung.', ['Messwerttabellen und gegebenenfalls Auswertungsdarstellungen'], [], 'Form von Versuchsprotokollen')
d(76,P,B, ['Eine fundierte Hypothese entwickeln und ein quantitatives Experiment zur Überprüfung entwerfen.', 'Den Versuch durchführen, die Hypothese auswertungsbasiert reflektieren und Ergebnisse präsentieren.'], 'Der gesamte offene Forschungszyklus deckt eigenständige Hypothesen-, Planungs-, Auswerte- und Präsentationsleistungen ab. Ohne konkrete Ausgangssituation ist kein einzelner Inhaltsnachweis definiert.', ['Hypothesenspezifische quantitative Auswertung nicht festgelegt'], ['Hypothesenbildung versus quantitative Versuchskonzeption versus Reflexion/Präsentation; Problemscope offen'], 'fundierte Hypothesen')
d(77,P,B, ['Bewegungsvideos aufnehmen und daraus Zeit, Ort, Geschwindigkeit und Beschleunigung ermitteln.', 'Aus diesen kinematischen Messgrößen auf wirkende Kräfte schließen.'], 'Die Videokinematik und die dynamische Rückschlussleistung können getrennt gelingen. Die wechselnden Bewegungsabläufe werden nicht zu einem begrenzten Modell eingeengt.', ['Video-Koordinatenauswertung und zeitliche Änderungsraten'], ['Videokinematik versus dynamischer Kraftschluss'], 'Anhand ihrer Messergebnisse schließen sie auf die wirkenden Kräfte')
d(78,S,Y,[], 'Jahrgang 11 platziert vier ABU11- und vier T11-Lernbereiche unter dem Fachroot. Der leere Text enthält keinen gemeinsamen ABU-/T-Leistungsstandard.', [], [], '')
d(79,S,C,[], 'Der Aspekte12-Elektrizitätscluster bündelt fünf Ziele unter der wörtlichen Profilangabe G,S,W, GH, IW. Der leere Beschreibungstext erlaubt weder eine eigene Kompetenz noch eine rechtliche Expansion dieser Kürzel.', [], [], '')
d(80,P,B, ['Stromkreisbauteile und ihre Funktionen erklären.', 'Stromkreisvorgänge mit mechanischen Analogien veranschaulichen.'], 'Auch im Aspekte12-Scope verlangt das vollständige Blatt sowohl funktionale Stromkreiskunde als auch eine Modellübertragung. Der Profilwechsel verkleinert diese beiden Inhaltsdimensionen nicht.', [], ['Bauteilfunktion versus mechanische Analogie'], 'mithilfe mechanischer Analogien')
d(81,P,B, ['Versuchsaufbau und Schaltplan ineinander übertragen.', 'Widerstände durch eigene Strom- und Spannungsmessungen mit Volt-/Amperemeter bestimmen.', 'Gemessene elektrische Größen hinsichtlich Gefahr bewerten.'], 'Im Aspekte12-Lernbereich bleiben Darstellungswechsel, praktische Widerstandsmessung und Sicherheit drei unterschiedliche Nachweise. Die gefährdungsbezogene Abwägung ist keine Orientierung.', ['Widerstandsquotient aus Spannung und Strom'], ['Plan/Aufbau-Translation versus Messgerätekompetenz versus Gefahrenbewertung'], 'Volt‑ und Amperemeter sachgerecht')
d(82,P,B, ['Eine Widerstandsschaltung planen und aufbauen.', 'Strom, Spannung, Leistung und Widerstand der Verbraucher bestimmen.', 'Haushaltsstromnetz oder Mehrfachsteckdose sicher dimensionieren.'], 'Der Aspekte12-Text reicht von praktischer Konstruktion bis zur netzweiten Lastabschätzung. Eine richtige Schaltungsrechnung belegt weder Aufbau noch Haushaltsdimensionierung.', ['Schaltungs-, Widerstands- und Leistungsgleichungen'], ['Praktischer Aufbau versus Größenbestimmung versus Haushaltslasten'], 'Mehrfachsteckdosen im Haushalt')
d(83,P,N, ['An einem elektrischen Gerät Stromwirkungen durch Energieumwandlung und Wirkungsgrad erklären.'], 'Im Aspekte12-Profil sind Stromwirkung und Effizienz dieselbe zusammenhängende Geräte-Energieerklärung. Der vollständige Text fordert keine zusätzliche vom Gerät unabhängige Rechenroutine.', ['Wirkungsgradverhältnis'], [], 'Wirkungen des elektrischen Stromes')
d(84,I,B, ['Möglichkeiten elektrischer Energieversorgung fachlich vergleichen.', 'Eine Nachhaltigkeitsposition dazu mit expliziten Kriterien begründen.'], 'Der Aspekte12-Auftrag enthält eine gesellschaftliche Nachhaltigkeitsbewertung neben der elektrischen Versorgungsphysik. Welche Quellen, Kriterien und Wege den vollständigen Nachweis bilden, bleibt offen.', [], ['Versorgungsphysik versus Nachhaltigkeitsargument; Kriterien-/Quellenscope offen'], 'fachlich fundiert über mögliche Wege')
d(85,S,C,[], 'Aspekte12 Optik ordnet fünf konkrete Ziele unter G,S,W, GH, IW. Der Titel nennt den Themenumfang und Zeitrahmen; der leere Text ist keine zusätzliche Optikkompetenz.', [], [], '')
d(86,P,B, ['Schattenbereiche sowie Sonnen-/Mondfinsternis mit Strahlengängen erklären.', 'Mondphasen anhand wechselnder Beleuchtungs- und Beobachtungsgeometrie erklären.'], 'Auch dieses Aspekte12-Blatt verknüpft Abschattung mit einem zweiten Mondphaseninhalt. Eine korrekte Schattenkonstruktion darf nicht als Nachweis der Mondphasenerklärung gelten.', ['Strahlen- und Beleuchtungsgeometrie'], ['Finsternis-/Schattenmodell versus Mondphasenmodell'], 'sowie der Mondphasen')
d(87,P,B, ['Reflexions- und Brechungsversuche planen und durchführen.', 'Brechungsindex und Totalreflexionsgrenzwinkel bestimmen und Lichtleiter erklären.'], 'Im Aspekte12-Ziel bleiben Reflexion, Brechung und Totalreflexion verschiedene Gesetzesbereiche. Der Rechen- und Lichtleiteranteil deckt einen eigenständigen Teil dieser Versuche ab.', ['Winkelmessung und Brechungsbeziehungen'], ['Reflexion versus Brechungsindexbestimmung versus Totalreflexion'], 'unterschiedlichen optischen Medien')
d(88,P,B, ['Sammellinsenabbildungen konstruieren und Bildgröße/-weite experimentell prüfen.', 'Abbildung im Auge mit Kurz- und Weitsichtigkeit erklären.'], 'Der Aspekte12-Scope enthält weiterhin zwei inhaltliche Modelle: optische Linsenabbildung und die Anwendung auf Sehfehler. Messkontrolle an einer Linse allein genügt nicht für beide.', ['Strahlenkonstruktion und Bildgrößen-/Bildweitenvergleich'], ['Linsenabbildung versus Augen-/Sehfehlermodell'], 'Bildentstehung im Auge')
d(89,I,B, ['Optische Geräte zur vorgegebenen Problemfrage recherchieren.', 'Historische Einordnung und aktuelle Alltagsbedeutung fachsprachlich präsentieren.'], 'Die vollständige Aspekte12-Beschreibung enthält explizit Geschichte und Gegenwartsbedeutung zusätzlich zum Geräteinhalt. Der unbenannte Recherchegegenstand verhindert einen engen Einzelziel-Scope.', [], ['Optischer Geräteinhalt versus Geschichte versus Bedeutung; Problemfrage offen'], 'aktuelle Bedeutung für den Alltag')
d(90,P,N, ['Mit primären und sekundären Lichtquellen direkten und gestreuten Lichteinfall beim Sehen erklären.'], 'Die beiden Lichtquellentypen sind hier die begrifflichen Teile einer einzigen Lichtweg-Erklärung. Der Aspekte12-Profilkontext verändert diese physikalische Zielart nicht.', [], [], 'Sehvorgang als direkten oder gestreuten Lichteinfall')
d(91,S,C,[], 'ABU12 Wärme als Energieform bündelt sieben Ziele von thermischen Größen über Gasprozesse bis Wärmeleitung. Die 40 Stunden sind Programminformation innerhalb eines fachlichen Clusters.', [], [], '')
d(92,P,B, ['Druck, Volumen, Temperatur und Wärmemenge physikalisch und fachsprachlich unterscheiden.', 'Die zugehörigen Größenwerte in andere Einheiten umrechnen.'], 'Begriffsverständnis der vier thermodynamischen Größen und Einheitenkonversion sind unabhängig nachweisbar. Die gemeinsame Liste ist eine Grundlagenübersicht, kein einzelner spezifischer Größenauftrag.', ['Einfache Einheitenumrechnungen'], ['Thermodynamische Größenabgrenzung versus Einheitenkonversion'], 'Druck, Volumen, Temperatur und Wärmemenge')
d(93,P,B, ['Mischtemperaturen bei unterschiedlichen spezifischen Wärmekapazitäten experimentell bestimmen und energetisch überprüfen.', 'Phasenübergänge in die Misch-Energiebilanz einbeziehen.'], 'Sensible Erwärmung/Kühlung und latente Übergangswärme erfordern unterschiedliche Bilanzteile. Das Bestehen einer Mischung ohne Phasenwechsel weist den ausdrücklich verlangten Phasenübergang nicht nach.', ['Massen-, Wärmekapazitäts- und Phasenwärmebilanz'], ['Mischung unterschiedlicher Wärmekapazitäten versus Mischung mit Phasenübergang'], 'auch Phasenübergänge')
d(94,P,B, ['Experimentelle Abhängigkeiten zwischen p, V und T grafisch bestimmen und zur allgemeinen Gasgleichung zusammenführen.', 'Die gefundenen Beziehungen im Modell idealer Gase interpretieren.'], 'Mehrere Zustandsrelationen, ihre Zusammenführung und ihre mikroskopische Modellinterpretation sind eigenständige Leistungsanteile. Diagramme und Algebra dienen dem Gasmodell.', ['p-V-T-Diagramme, Proportionalitäten und Gleichungszusammenführung'], ['Einzelne Gasrelationen versus allgemeine Gasgleichung versus Teilchenmodellinterpretation'], 'Modellvorstellung für ideale Gase')
d(95,P,N, ['Eine beobachtete ideale Gaszustandsänderung mit der allgemeinen Gasgleichung quantitativ erklären.'], 'Druck, Temperatur oder Volumen sind wechselnde Unbekannte desselben Gasgesetzmodells. Kühlschrank, Luftbläschen und Reifen geben alternative Alltagskontexte, keine zusätzlichen unabhängigen Zielprinzipien.', ['Allgemeine Gasgleichung nach Zustandsgrößen auflösen'], [], 'abgedichteter Kühlschrank, aufsteigende Luftbläschen')
d(96,P,N, ['Die in einem p-V-Kreisprozess verrichtete mechanische Arbeit aus der eingeschlossenen Diagrammfläche bestimmen und physikalisch deuten.'], 'Flächenbestimmung und Deutung sind zusammen die eine Gasprozess-Arbeitsleistung. Ihr Gegenstand ist verrichtete Arbeit, nicht ein allgemeiner Mathematik-Flächenkurs.', ['Fläche eines geschlossenen p-V-Pfads'], [], 'Arbeit an oder von einem idealen Gas')
d(97,P,N, ['Druck- und Temperaturänderungen eines realen Prozesses hinsichtlich Wirkungsgrad und Umwandlungsqualität beurteilen.'], 'Die Qualitätsbewertung verwendet ausdrücklich denselben Wirkungsgrad als physikalisches Kriterium. Sie verlangt keine eigenständigen politischen oder wirtschaftlichen Wertmaßstäbe.', ['Wirkungsgradvergleich gegebenenfalls quantitativ'], [], 'Qualität von Energieumwandlungen')
d(98,P,N, ['Aus vorbereiteten Wärmeleitungsquellen Maßnahmen zur Beeinflussung des Wärmetransports fachsprachlich und adressatengerecht darstellen.'], 'Quellenauswertung und Präsentation münden in eine inhaltlich gebundene Wärmeleitungsbeurteilung. Die Abkühlkurven liefern physikalische Evidenz für diesen Transportmechanismus.', ['Abkühlkurvenvergleich'], [], 'thermisch isolierten und nicht isolierten Systemen')
d(99,S,C,[], 'ABU12 Dynamik von Flüssigkeiten und Gasen enthält vier Ziele zu Kontinuität, Bernoulli, Anwendungen und Viskosität. Die leere Beschreibung ist ein fachlicher Bündeltitel.', [], [], '')
d(100,P,B, ['Strömungsgeschwindigkeit und Durchflussquerschnitt sprachlich/mathematisch über Kontinuität verbinden.', 'Laminare und turbulente Strömungen unterscheiden und Wirbelentstehung erklären.'], 'Die quantitative Querschnittsbeziehung und die qualitative Strömungsregime-/Wirbelerklärung sind verschiedene physikalische Inhalte. Der Text fordert beide unabhängig von einem konkreten Praxisbeispiel.', ['Fläche-Geschwindigkeit-Beziehung'], ['Kontinuitätsbeziehung versus Strömungsregime und Wirbelentstehung'], 'laminaren und turbulenten Strömungen')
d(101,P,N, ['Das Bernoulli-Gesetz aus mechanischen Prinzipien herleiten und Staudruck als Folgerung erklären.'], 'Staudruck ist eine bestimmte Anwendung derselben Energie-/Druckherleitung. Die algebraische Arbeit ist Teil einer physikalischen Argumentation.', ['Mechanische Energiebilanz und algebraische Druckbeziehungen'], [], 'entwickeln daraus die Größe Staudruck')
d(102,P,N, ['Ein Strömungsphänomen mithilfe von Kontinuität und Bernoulli erklären.'], 'Hausdach, Geschwindigkeitsmessung und hydrodynamisches Paradoxon sind unterschiedliche Anwendungen einer gemeinsamen Strömungserklärung. Es wird keine weitere eigenständige mathematische Methode formuliert.', ['Kontinuitäts- und Bernoulli-Beziehungen'], [], 'hydrodynamische Paradoxon')
d(103,P,B, ['Die Geschwindigkeitsverteilung im Rohr aus innerer Reibung und Viskosität erklären.', 'Rohrquerschnitt und Durchflussrate passend dimensionieren.'], 'Die kausale Profilbeschreibung und die technische Dimensionierung benötigen eigene Evidenz. Der Text nennt kein enges quantitatives Modell oder Randbedingungen für diese zweite Leistung.', ['Rohrflächen-/Durchflussbeziehung; quantitatives Modell offen'], ['Viskoses Geschwindigkeitsprofil versus Durchflussdimensionierung; Modellgrenzen offen'], 'Rohrquerschnittsfläche und Durchflussrate passend')
d(104,S,C,[], 'T12 Kreisbewegung ist ein Cluster aus vier Zielen zu Kreiskinematik, radialer Messauswertung, Verkehrsgrenzen und Satelliten. Er formuliert keine zusätzliche Kreisbewegungsleistung.', [], [], '')
d(105,P,B, ['Drehbewegungen als gleichförmige Kreisbewegung mit den charakteristischen kinematischen Größen modellieren.', 'Ihre Dynamik über Zentripetalbeschleunigung und -kraft erklären.'], 'Das T12-Blatt enthält dieselbe eigenständige Trennung zwischen Kreiskinematik und verursachender Kraftdynamik. Windrad, Karussell und Datenträger sind nur wechselnde Beispielsysteme.', ['Kreisgeometrie, Winkel-/Bahngeschwindigkeit und Frequenzbeziehungen'], ['Kreisgrößenkinematik versus Radialdynamik'], 'Windrad, Karussell, Datenträger')
d(106,P,N, ['Radiale Beschleunigungs- und Kraftabhängigkeiten aus Messreihen mit Newtonschen Gesetzen formulieren.'], 'Die Kraft und Beschleunigung sind im T12-Messauftrag explizit durch Newton verbunden. Die Auswertung untersucht einen gemeinsamen radialen Zusammenhang statt eine abstrakte Funktionsklasse.', ['Messwertrelationen von Radius und Winkelgeschwindigkeit'], [], "unter Verwendung der Newton'schen Gesetze")
d(107,P,B, ['Kurvenfahrten mit resultierender Zentripetalkraft modellieren und Geschwindigkeitsgrenzen beurteilen.', 'Die Notwendigkeit von Kurvenüberhöhungen aus der Kraftgeometrie beurteilen.'], 'Die T12-Fassung fügt Kurvenüberhöhung hinzu, deren Kraftkomponenten eigenständig zu begründen sind. Eine ebene Kurve mit berechneter Höchstgeschwindigkeit deckt die Überhöhung nicht ab.', ['Kreisbewegung, Kräfteaddition und gegebenenfalls Neigungsgeometrie'], ['Ebene Kurvenfahrt/Geschwindigkeitsgrenze versus Kurvenüberhöhung'], 'Geschwindigkeitsbegrenzungen im Straßenverkehr und Kurvenüberhöhungen')
d(108,P,B, ['Satellitenbahnen mit Newtonscher Gravitation als gleichförmige Kreisbewegung modellieren.', 'Einsatzmöglichkeiten von Satelliten für Kommunikation, Navigation und Beobachtung beurteilen.'], 'Das Bahnmodell und die Eignung für verschiedene Anwendungen sind getrennt prüfbar. Anwendungskriterien und der Bezug zwischen Bahneigenschaft und konkretem Einsatz bleiben unbenannt.', ['Gravitations- und Kreisbewegungsgleichungen'], ['Orbitales Kraftmodell versus anwendungsspezifische Satelliteneignung'], 'Nachrichtenübertragung, Navigation, Wetterbeobachtung, Kartografie')
d(109,S,C,[], 'T12 Mechanische Schwingungen und Wellen enthält zehn Ziele mit deutlich verschiedenen Inhalten von Amplitudenmessung bis Resonatorgrenzen. Der Stundenrahmen und leere Text bilden ein fachliches Cluster.', [], [], '')
d(110,P,N, ['Amplitude, Periodendauer und Frequenz einer Schwingung in einem selbst geplanten geeigneten Messversuch bestimmen.'], 'Die drei Größen charakterisieren gemeinsam denselben beobachteten Schwingungsvorgang. Planung und Messverfahren dienen diesem begrenzten Größenbestimmungsauftrag.', ['Zeit-/Elongationsauswertung und Kehrwert von Periodendauer'], [], 'Amplitude, Periodendauer sowie Frequenz')
d(111,P,B, ['Orts-, Geschwindigkeits- und Beschleunigungsverläufe harmonischer Schwingungen mit Anfangsbedingungen trigonometrisch modellieren.', 'Harmonische Schwingungen mit Zeigerdiagrammen darstellen.'], 'Drei zeitliche Größenverläufe und die eigene rotierende Zeigerdarstellung sind mehrere nachweisbare Inhalts-/Repräsentationsleistungen. Die Formeln sind physikalische Schwingungsmodelle, keine unabhängige Trigonometrieprüfung.', ['Trigonometrische Funktionen, Phasen-/Anfangsparameter und Zeigerdiagramme'], ['Drei phasenverschobene kinematische Verläufe versus Zeigerrepräsentation'], 'Orts‑, Geschwindigkeits‑ und Beschleunigungskoordinaten')
d(112,P,N, ['Aus gezielter grafischer Auswertung die Systemgrößen bestimmen, von denen die Schwingungsperiodendauer abhängt.'], 'Faktoridentifikation und Funktionsauswertung beziehen sich auf genau die Periodendauer eines betrachteten Systems. Das System muss in einer Aufgabe festgelegt werden, aber das Inhaltsziel bleibt dieser Zusammenhang.', ['Grafische funktionale Abhängigkeitsauswertung'], [], 'von denen die Periodendauer abhängt')
d(113,P,B, ['Eine harmonische Schwingung aus dem linearen Rückstellkraftgesetz begründen und die Richtgröße bestimmen.', 'Richtgröße mit Eigenfrequenz, Periodendauer, Energie, Amplitude und Masse verknüpfen.'], 'Die Harmonizitätsbegründung und das gesamte Netz charakteristischer Energie-/Zeitgrößen sind unabhängig assessierbar. Mehrere Pendeltypen verlangen zusätzlich unterschiedliche Rückstellkraftmodelle.', ['Lineares Kraftgesetz und Schwingungsgrößenrelationen'], ['Harmonizitätskriterium versus Zeitgrößen- und Energierelationen; Pendelmodelle'], 'Eigenfrequenz, Periodendauer, Schwingungsenergie, Amplitude, Masse')
d(114,P,B, ['Energieformen harmonischer Schwingungen über Zeit und Elongation grafisch/quantitativ bilanzieren.', 'Dämpfungseffekte qualitativ erklären.'], 'Die ideale Energieumwandlung und das dissipative Dämpfungsmodell sind getrennte physikalische Leistungen. Zeit- und Ortsabhängigkeit bilden weitere explizite Darstellungskriterien.', ['Energiegraphen über t und Elongation; Energiebilanz'], ['Ideale Schwingungsenergiebilanz versus Dämpfung; Zeit- versus Ortsdarstellung'], 'erklären qualitativ Dämpfungseffekte')
d(115,P,B, ['Longitudinale und transversale Wellenausbreitung erklären.', 'Räumliches Fortschreiten und örtliche Schwingung mit Phasen-/Zeigerdiagrammen und Wellengleichung vorhersagen.'], 'Wellentypen/Entstehung und quantitative Raum-Zeit-Prognose erfordern eigenständige Nachweise. Die Wellengleichung ist der mathematische Träger dieser physikalischen Aussagen.', ['Raum-Zeit-Wellengleichung, Phasenlagen und Zeigerdiagramme'], ['Wellentyp-/Entstehungsmodell versus quantitative Raum-Zeit-Phasenprognose'], 'an einem festen Ort')
d(116,P,N, ['Die qualitative Beugung einer ebenen Wellenfront an Einfachspalten verschiedener Breite mit Huygens und Superposition prognostizieren und überprüfen.'], 'Zwei Prinzipien unterstützen dasselbe begrenzte Beugungsphänomen. Der qualitative Spaltbreitenvergleich ist die eine Zielrelation, keine zusätzliche mathematische Analyseleistung.', ['Qualitative Wellenfrontkonstruktion oder Simulation'], [], 'Einfachspalt verschiedener Breite')
d(117,P,B, ['Interferenzorte verschiedener Ordnung bei Doppelspalt oder zwei kohärenten Erregern quantitativ bestimmen.', 'Knoten und Bäuche zweier entgegenlaufender Wellen zur Wellenlänge in Beziehung setzen.'], 'Zwei-Quellen-Interferenz und stehende Wellen sind verschiedene geometrische Systeme. Ein korrektes Doppelspaltmaximum weist die Knotenabstände einer stehenden Welle nicht nach.', ['Wegdifferenzrechnung und Zeigerdiagramme; Wellenlängenrelationen'], ['Zwei-Quellen-Interferenz versus stehende Welle'], 'zwei entgegenlaufenden Wellenzügen')
d(118,P,N, ['Diskrete Resonanz schwingungsfähiger Körper qualitativ erklären und daraus Maßnahmen zur Beeinflussung eines Alltagsphänomens beurteilen.'], 'Die Maßnahmenbewertung setzt die gleiche Resonanzursache und Frequenzbedingung im gewählten System um. Musikinstrumente, Fahrzeug- oder Maschinenvibration sind alternative Kontexte.', [], [], 'Resonanz schwingungsfähiger Körper bei diskreten Frequenzwerten')
d(119,P,B, ['Reflexionen von Wellen am festen und losen Ende über ihre Phase unterscheiden.', 'Resonatorabmessungen mit möglichen Eigenfrequenzen für eindimensionale Resonanz verbinden.'], 'Die Randreflexionsbedingung und die quantitative Eigenfrequenzreihe sind eigenständige Inhaltsnachweise. Die Tonerzeugung in Orgelpfeifen ist eine Anwendung des zweiten Anteils.', ['Phasenausbreitung und Resonatorlängen-/Frequenzrelationen'], ['Feste/lose Randreflexion versus eindimensionale Eigenfrequenzbedingung'], 'Reflexionen am festen und losen Ende')
d(120,S,C,[], 'T12 Klassische Felder ordnet sechs Ziele zu Feldlinien, Stärke/Potenzial, geladener Bewegung und Kondensatoren. Das Feldthema ist ein Cluster, keine Kompetenzachse.', [], [], '')
d(121,P,N, ['Ein klassisches Feld aus experimenteller Evidenz oder Software als Feldlinienbild darstellen und Homogenität/Symmetrie daraus begründet deuten.'], 'Feldlinienerstellung und Eigenschaftsaussage bilden die eine feldgebundene Repräsentationskompetenz. Superposition ist bei Quellenfeldern ein passendes Konstruktionsmittel derselben Leistung.', ['Gegebenenfalls geometrische Feldsuperposition'], [], 'insbesondere Homogenität und Symmetrie')
d(122,P,B, ['Elektrische Feldstärke aus der Kraft auf eine Probeladung bestimmen.', 'Magnetische Flussdichte aus der Kraft auf einen stromdurchflossenen Leiter bestimmen.'], 'Elektrisches und magnetisches Feld benutzen unterschiedliche Probensysteme und Kraftgesetze. Die allgemeine Feldstärkeidee vereinigt diese beiden konkreten Mess-/Berechnungsleistungen nicht zu einer einzigen.', ['Kraft-Ladungs-Quotient beziehungsweise Leiterkraftbeziehung'], ['Elektrische Probeladungsdefinition versus magnetische Leiterkraftdefinition'], 'eine Probeladung bzw. einen stromdurchflossenen Leiter')
d(123,P,B, ['Potenzialverläufe aus der Lageenergie in homogenen Quellenfeldern gewinnen.', 'Feldstärkeverläufe aus der Kraft bestimmen und mit dem Potenzial verbinden.'], 'Energiebezogenes Potenzial und kraftbezogene Feldstärke sind zwei fachliche Größen mit unterschiedlichen Definitionen. Der Text setzt sichere mathematische Zusammenhänge voraus, benennt aber den genauen Verknüpfungsnachweis nicht.', ['Funktionale Lageenergie-/Potenzial- und Kraft-/Feldstärkebeziehungen'], ['Potenzialdefinition versus Feldstärkedefinition; mathematische Verknüpfung unspezifiziert'], 'Potenzial und Feldstärke')
d(124,P,N, ['Die Bewegung eines makroskopisch geladenen Körpers im homogenen elektrostatischen Feld mit geeignetem Kraft-/Energiemodell prognostizieren.'], 'Die Prinzipienliste bezeichnet alternative oder zusammenhängende Lösungswerkzeuge für dieselbe Bewegungsmodellierung. Es ist kein zusätzliches abstraktes Energie- oder Vektorlernziel formuliert.', ['Kräftepläne, Koordinatenbewegungen und gegebenenfalls Energiebilanz'], [], 'makroskopischer, elektrisch geladener Körper')
d(125,P,B, ['Kapazität, Ladung und Energie eines Kondensators mit oder ohne Dielektrikum bestimmen.', 'Unterschiedliche Kondensatorbauformen als Ladungs- oder Energiespeicher dimensionieren.'], 'Statische Kennwerte, Dielektrikumeinfluss und bauteilbezogene Einsatzwahl sind getrennte Nachweise. Dreh-, Elektrolyt- und Superkondensator lassen sich nicht durch einen einzigen idealen Kondensatorwert vertreten.', ['Kapazitäts-, Ladungs- und Energiebeziehungen'], ['Kennwertbestimmung versus Dielektrikumeffekt versus bauformspezifische Dimensionierung'], 'Drehkondensatoren, Elektrolytkondensatoren, Superkondensatoren')
d(126,P,B, ['Einen Kondensatorversuch einschließlich elektronischer Messung planen und durchführen.', 'Kapazität, Ladung und Energieinhalt auch indirekt aus den Versuchsdaten bestimmen.'], 'Die freie Versuchsplanung und verschiedene direkte/indirekte Kennwertermittlungen sind ein breiter Praktikumsauftrag. Die Entladekurve ist nur ein Beispiel und schränkt die geforderten Messziele nicht ein.', ['Kondensatordaten- und gegebenenfalls Entladekurvenauswertung'], ['Versuchsauswahl versus Kapazitäts-/Ladungs-/Energieermittlung; indirekte Methode offen'], 'auch indirekt')
d(127,S,C,[], 'T12 Elektromagnetische Induktion enthält drei Ziele zu Flussdiagrammen, Sonderfällen und Spulenschaltvorgängen. Die leere Beschreibung macht den Lernbereich zu einem Inhaltscluster.', [], [], '')
d(128,P,N, ['Den zeitlichen Verlauf der Induktionsspannung aus einem t-Φ-Diagramm mit dem Induktionsgesetz bestimmen.'], 'Der Ableitungsschritt dient genau der physikalischen Spannungsprognose aus dem magnetischen Fluss. Vorgegebene und gemessene Diagramme sind Eingabevarianten, keine unabhängige Mathematikkompetenz.', ['Differenzialrechnung des zeitlichen Flussverlaufs'], [], 'mathematischen Kenntnisse hinsichtlich der Differenzialrechnung')
d(129,P,N, ['Für konstante Flussdichte oder konstante Feldfläche mit dem Induktionsgesetz eine technisch nutzbare Induktionsspannung bestimmen.'], 'Die beiden ausdrücklich genannten Sonderfälle sind Varianten derselben Flussänderungsrechnung. Die technische Größenordnung liefert ein Plausibilitätskriterium für die Spannungsberechnung.', ['Flussänderung aus zeitabhängiger Fläche oder Flussdichte'], [], 'zeitlich konstanten magnetischen Flussdichte')
d(130,P,B, ['Ein- und Ausschaltverläufe von Spannung/Strom in Spulenkreisen qualitativ beschreiben.', 'Ausschaltüberspannung anhand magnetischer Feldenergie hinsichtlich Nutzen/Risiko beurteilen.', 'Induktivität und Leitungswiderstand realer Spulen beim Einschalten bestimmen.'], 'Schalttransienten, technische Überspannungsbewertung und quantitative Spulenparameter sind drei eigenständige Leistungsdimensionen. Eine qualitative Kurve belegt die Parameterbestimmung nicht.', ['Induktionsgesetz, zeitliche Kurven und Spulenenergierelation'], ['Ein-/Ausschaltverlauf versus Überspannungs-/Energierisiko versus reale Spulenparameter'], 'Induktivitäten und Leitungswiderstände realer Spulen')
d(131,S,Y,[], 'Jahrgang 12 platziert jeweils zwei Aspekte12- und ABU12- sowie vier T12-Lernbereiche. Diese gemischte Programmplatzierung darf nicht als ein gemeinsamer fachlicher Ziel- oder Profilabschluss behandelt werden.', [], [], '')
d(132,S,C,[], 'Aspekte13 Mechanik I ordnet sechs konkrete Ziele unter der wörtlichen Profilgruppe G,S,W, GH, IW. Der leere Beschreibungstext ist ein Themenrahmen und keine ausdrückliche Mechanikkompetenz.', [], [], '')
d(133,P,B, ['Dichte von festen und flüssigen Stoffen experimentell ermitteln.', 'Daraus Schwimm-, Schwebe-, Sink- und Aufsteigverhalten vorhersagen.'], 'Im Aspekte13-Ziel sind Stoffgrößenmessung und Auftriebsprognose weiterhin getrennte physikalische Erfolge. Der Jahrgangstitel verleiht dem zusammengesetzten Text keine höhere atomare Granularität.', ['Masse-Volumen-Quotient; Dichtevergleich'], ['Stoffdichtemessung versus Verhalten im umgebenden Medium'], 'Schweben und Schwimmen, Absinken und Aufsteigen')
d(134,P,N, ['In einem angeleiteten Bewegungsversuch aus eigenen Messwerten mittlere Geschwindigkeitsbeträge bestimmen.'], 'Der vollständige Aspekte13-Text richtet Planung, Durchführung und Auswertung auf dieselbe mittlere Geschwindigkeit. Er beschreibt keinen zusätzlichen Momentangeschwindigkeits- oder Kraftnachweis.', ['Wegänderung pro Zeitintervall'], [], 'mittleren Geschwindigkeiten der bewegten Körper')
d(135,P,B, ['Bewegungen durch passende Darstellungen dokumentieren.', 'Ortsänderung und Geschwindigkeit einschließlich Momentangeschwindigkeit daraus vergleichen.'], 'Die Aspekte13-Fassung enthält einen eigenständigen Dokumentationsauftrag und eine weitergehende lokale Bewegungsdeutung. Die Wahl der Darstellung und der genaue Vergleichsmaßstab bleiben offen.', ['Bewegungsdiagramme und lokale Änderungsraten'], ['Bewegungsdokumentation versus Momentangeschwindigkeits-/Ortsvergleich'], 'auch Momentangeschwindigkeit')
d(136,P,N, ['Kraftwirkungen auf einen Bewegungszustand qualitativ aus Kraftidentifikation, Superposition und Beharrung vorhersagen.'], 'Im Aspekte13-Kontext sind die Teilhandlungen eine einzige qualitative Dynamikbegründung. Die Auswahl zwischen Superposition und Beharrung dient der jeweiligen betrachteten Kraftsituation.', ['Gegebenenfalls zeichnerische Kraftüberlagerung'], [], 'Wirkung von Kräften auf den Bewegungszustand')
d(137,P,B, ['Haft- und Gleitreibungskoeffizienten aus gemessenen Reibungskräften bestimmen.', 'Technische Reibungs- und Bremsvorgänge mit diesen Erkenntnissen diskutieren.'], 'Das Aspekte13-Blatt kombiniert zwei Reibungszustände mit einer eigenständigen technischen Transferleistung. Messwerte von Gleitreibung sichern weder die Haftgrenze noch die Bremsdiskussion.', ['Reibungs-/Normalkraftquotient'], ['Haftgrenze versus Gleitreibung; Messkoeffizienten versus technische Bremsfolgen'], 'technisch relevante Reibungsvorgänge')
d(138,P,N, ['Kraftwirkungen an einer geneigten Ebene im Hinblick auf sicheres Verkehrsverhalten erklären und diskutieren.'], 'Die Diskussion bleibt in der Aspekte13-Fassung auf das bestimmte Kraftmodell der Schräge begrenzt. Sie ist ein physikalischer Transferauftrag, kein bloßer Relevanzeinstieg.', ['Gegebenenfalls Kraftkomponentendarstellung'], [], 'ein sicheres Verhalten im Straßenverkehr')
d(139,S,C,[], 'Aspekte13 Mechanik II bündelt fünf Blätter zu Maschinen, Energie und physikalischen Größen. Der leere Text enthält keine zusätzliche überprüfbare Hebel- oder Energieleistung.', [], [], '')
d(140,P,B, ['Hebelgesetzmäßigkeiten experimentell untersuchen.', 'Feste/lose Rollen und Flaschenzüge experimentell untersuchen und protokollieren.'], 'Der Aspekte13-Text nennt ausdrücklich mehrere unterschiedliche einfache Maschinen. Ein Hebelexperiment ist kein vollständiger Nachweis der Rollen- und Flaschenzugleistungen.', ['Kraft-/Wegverhältnisse und Hebelarme'], ['Hebel versus feste/lose Rolle und Flaschenzug'], 'loser, fester Rolle und Flaschenzug')
d(141,P,N, ['Die technische Funktion eines Hebelgeräts aus Kräften, Drehpunkt und Hebelgesetz analysieren und bewerten.'], 'Die vollständige Aspekte13-Beschreibung verbindet Identifikation und Relevanzbewertung an derselben Gerätefunktion. Damit ist eine einzelne Hebelanalyse als enger Kandidat möglich.', ['Kraft-Hebelarm-Zusammenhang'], [], 'die wirkenden Kräfte und den Drehpunkt')
d(142,P,N, ['Einen mechanischen Alltags-, Technik- oder Naturvorgang idealisiert als Energieumwandlung fachsprachlich beschreiben.'], 'Der Aspekte13-Text fordert genau die Energieumwandlungsperspektive auf einen Vorgang. Die korrekte Sprache ist ein Evidenzkriterium dieser Beschreibung.', [], [], 'fachsprachlich korrekte Formulierungen')
d(143,P,B, ['Ort und Momentangeschwindigkeit mithilfe mechanischer Arbeits-/Energieerhaltung bestimmen.', 'Reale Reibungsverluste in die Bilanz einbauen.'], 'Die Aspekte13-Fassung verbindet ideale Bewegung und Dissipation mit einem offenen Zeitpunktauftrag. Energie allein legt ohne weiter benannte Dynamik nicht allgemein die Zeit-Ort-Abhängigkeit fest.', ['Energie- und Arbeitsgleichungen'], ['Ideale Energieprognose versus dissipative Bilanz; Zeitmodell unbestimmt'], 'Aufenthaltsort und die Momentangeschwindigkeit')
d(144,P,B, ['Die Begriffe Kraft, Energie, Arbeit und Leistung samt Beziehungen/Einheiten unterscheiden.', 'Einheiten von Energie und Arbeit sicher konvertieren.'], 'Im Aspekte13-Ziel bleiben die begriffliche Größenkarte und die arithmetische Konversion eigenständige Leistungen. Einheitenwechsel ist hier eine physikalisch gebundene Routine, kein eigenständiges Mathematikfachziel.', ['Energie-/Arbeitseinheiten konvertieren'], ['Viergrößenkonzept versus numerischer Einheitenwechsel'], 'verschiedenen Einheiten von Energie und Arbeit')
d(145,S,C,[], 'Aspekte13 Wärmelehre ordnet acht Ziele zu Teilchenmodell, Temperatur, kalorischen Größen und Transport. Der Lernbereichstitel beschreibt ein fachliches Bündel innerhalb Jahrgang 13.', [], [], '')
d(146,P,N, ['Festes, flüssiges und gasförmiges Verhalten mit dem Teilchenmodell für ein Alltagsphänomen erklären.'], 'Im Aspekte13-Blatt sind drei Aggregatzustände Gegenfälle desselben physikalischen Modells. Die Beschreibung fordert keine chemische Zusammensetzungs- oder Reaktionslehre.', [], [], 'mithilfe des Teilchenmodells')
d(147,P,B, ['Thermische Längenänderungen experimentell quantifizieren und berechnen.', 'Thermische Volumenänderungen von Festkörpern und Flüssigkeiten experimentell quantifizieren und berechnen.'], 'Die Aspekte13-Fassung umfasst unterschiedliche geometrische Größen und Stoffklassen. Eine Längenausdehnungsbestimmung ersetzt keinen Volumen-/Flüssigkeitsnachweis.', ['Messwertbasierte Ausdehnungsmodelle'], ['Lineare Ausdehnung versus volumetrische Ausdehnung und Stoffscope'], 'in Abhängigkeit von der Temperaturänderung')
d(148,P,N, ['Das Ausdehnungsprinzip eines Thermometers erklären und für eine Messaufgabe ein geeignetes Gerät auswählen.'], 'Die Auswahl im Aspekte13-Text ist eine Anwendung derselben thermometrischen Funktionskenntnis. Beide Schritte lassen sich als ein Gerätebegründungsauftrag prüfen.', [], [], 'Längen‑ bzw. Volumenänderung')
d(149,P,N, ['Im Teilchenmodell den absoluten Nullpunkt begründen und die Kelvin-Temperaturskala daraus entwickeln.'], 'Die Skalenentwicklung folgt unmittelbar derselben physikalischen Nullpunktbegründung. Der Aspekte13-Kontext fügt keinen selbständigen abstrakten Zahlenskaleninhalt hinzu.', ['Temperaturskalenbezug'], [], 'eines absoluten Temperaturnullpunktes')
d(150,P,N, ['Spezifische Wärmekapazität eines Stoffes aus Wärme- und Temperaturmessdaten bestimmen.'], 'Die gesamte Aspekte13-Auswertung richtet sich auf genau einen Stoffparameter. Unterschiedliche Stoffzustände verändern nicht die Art dieses physikalischen Messziels.', ['Wärme-Masse-Temperaturrelation'], [], 'Zu‑ bzw. Abfuhr von Wärme')
d(151,P,N, ['Eine gemessene Flüssigkeits-Mischtemperatur bei gleicher Wärmekapazität mit der Mischungsregel kontrollieren.'], 'Experiment und Rechenkontrolle beziehen sich im Aspekte13-Ziel auf dasselbe klar begrenzte Mischmodell. Ungleiche Wärmekapazitäten und Phasenwechsel sind hier nicht enthalten.', ['Massen-/Temperaturbilanz'], [], 'anhand der Mischungsregel')
d(152,P,B, ['Phasenwechsel mikroskopisch im Teilchenmodell erklären.', 'Schmelz-/Verdampfungswärme quantitativ für Wärmespeicherung oder Kühlung nutzen.'], 'Der Aspekte13-Text fordert sowohl die Modellursache als auch eine kalorische Rechnung mit unterschiedlichen Übergangsarten. Die Erklärung eines Phasenwechsels sichert die Latentwärmebilanz nicht.', ['Masse mal spezifische Übergangswärme'], ['Mikroskopischer Phasenwechsel versus quantitative Übergangswärme'], 'Latentwärmespeichern oder Kühlakkus')
d(153,P,B, ['Wärmeleitung und Wärmestrahlung mit einfachen Modellen erklären.', 'Konvektion aus Temperatur-/Dichteunterschieden begründen und saisonale Gewässerschichtungen erklären.'], 'Auch im Aspekte13-Lernbereich stehen drei verschiedene Transportmechanismen nebeneinander. Der konkrete Gewässertransfer gehört zur Konvektion und deckt die anderen beiden Modelle nicht mit ab.', [], ['Leitung versus Strahlung versus Konvektion und Gewässertransfer'], 'Konvektion in Flüssigkeiten')
d(154,S,C,[], 'T13 Geladene Teilchen enthält drei breite Blätter zu Felddynamik, Ladungsbestimmung und Forschungsgesellschaft. Der Cluster selbst besitzt keine Leistungsbeschreibung.', [], [], '')
d(155,P,B, ['Geladene Teilchen in homogenen elektrischen und magnetischen Feldern modellieren.', 'Geschwindigkeitsfilter und Massenspektrometer quantitativ erklären.', 'Teilchenbeschleuniger unter relativistischen Effekten diskutieren.'], 'Elektrische, magnetische und kombinierte Felddynamik sowie relativistische Beschleuniger sind verschiedene Inhaltsmodelle. Die große Geräteliste ist keine enge einzelne Kompetenz.', ['Kraft-/Bahngleichungen und relativistische Energie-/Impulsbeziehungen'], ['Elektrisches versus magnetisches/kombiniertes Feld; Filter/Spektrometer versus relativistischer Beschleuniger'], 'auch unter Berücksichtigung relativistischer Effekte')
d(156,P,B, ['Teilchenladung und spezifische Ladung aus passenden experimentellen Aufbauten/Messdaten bestimmen.', 'Ladungsquantelung und relativistische Massezunahme aus den Ergebnissen begründen.'], 'Ladung, q/m, Quantelung und Relativität benötigen unterschiedliche Versuchsideen und Schlussfolgerungen. Die zwei Kennwerte und zwei Deutungen sind unabhängig nachweisbare physikalische Anteile.', ['Ladungs- und spezifische Ladungsrechnung; relativistische Relationen'], ['Absolute Ladung versus spezifische Ladung; Quantelung versus relativistische Änderung'], 'Ladungsquantelung und relativistischen Massezunahme')
d(157,I,B, ['Die Bedeutung großer Hochenergieanlagen für physikalische Grundlagenforschung und Weltbildwandel quellenbasiert beurteilen.', 'Zu gesellschaftspolitischer Kritik einen begründeten Standpunkt entwickeln.'], 'Der Text verlangt ausdrücklich eine gesellschaftspolitische Position zusätzlich zur physikalisch-historischen Forschungsbeurteilung. Dies ist ein Leistungsauftrag mit Quellen und kein motivationaler Orientierungsanker.', [], ['Forschungs-/Weltbildbeurteilung versus gesellschaftspolitische Position; Quellenkriterien offen'], 'gesellschaftspolitischen Kritik')
d(158,S,C,[], 'T13 Elektromagnetische Schwingungen und Wellen enthält elf Ziele vom LC-Kreis über Dipole bis Spektren und Gitter. Es ist ein Inhaltscluster ohne eigene prüfbare Beschreibung.', [], [], '')
d(159,P,B, ['Die freie LC-Schwingung durch das Zusammenwirken von Kondensator und Spule erklären.', 'Dämpfungseffekte auf reale Spannungs-/Stromverläufe qualitativ erörtern.'], 'Ideale Entstehungsmechanik und reale Dissipation sind eigenständig nachweisbar. Ein korrekter idealer LC-Zyklus erklärt die Dämpfung eines realen Kreises nicht automatisch.', ['Qualitative zeitliche Spannung-/Stromdarstellung'], ['Idealer LC-Mechanismus versus reale Dämpfung'], 'realen elektromagnetischen Schwingkreis')
d(160,P,B, ['Spannung, Strom, Ladung und Feldenergien eines idealen LC-Kreises mit trigonometrischen Funktionen zeitlich modellieren.', 'Energieerhaltung quantitativ anwenden und Eigenfrequenz mit Kapazität/Induktivität verknüpfen.'], 'Mehrere phasenverschobene Größenverläufe, Energiebilanzen und die Frequenz-Kennwertbeziehung sind eigenständige Inhalte. Die mechanische Analogie ist eine Hilfe innerhalb der elektromagnetischen Zielphysik.', ['Trigonometrische Zeitverläufe, Graphen und LC-Energie-/Frequenzrelationen'], ['Zeit-/Phasenmodelle mehrerer LC-Größen versus Energiebilanz versus Eigenfrequenzrelation'], 'Spannung, Stromstärke, Ladung sowie elektrischer und magnetischer Feldenergie')
d(161,P,B, ['LC-Kreise für vorgegebene Eigenfrequenzen mit der Thomson-Gleichung dimensionieren.', 'Rückkopplung zur Erzeugung ungedämpfter Schwingungen einsetzen.'], 'Passive Frequenzdimensionierung und aktive Rückkopplung sind verschiedene technische/physikalische Konzepte. Eine richtig gewählte Kapazität belegt kein Verständnis der Rückkopplung.', ['Thomson-Gleichung umstellen'], ['LC-Frequenzdimensionierung versus aktive Rückkopplung'], 'Prinzip der Rückkopplung')
d(162,P,B, ['Resonatorspannung über der Erregerfrequenz bei induktiv gekoppelten Kreisen darstellen.', 'Phasenverschiebung über der Frequenz darstellen und optimale Energieübertragung im Resonanzfall begründen.'], 'Amplituden- und Phasengang sind getrennte Mess- und Interpretationsnachweise. Der gemeinsame Resonanzkontext macht sie zu einem sinnvollen Bündel, aber nicht zu genau einem Inhaltsziel.', ['Frequenzgang- und Phasengangdiagramme'], ['Amplitudenfrequenzgang versus Phasenfrequenzgang und Kopplungseffizienz'], 'Phasenverschiebung zwischen der Erreger‑ und Resonatorspannung')
d(163,P,B, ['Den λ/2-Dipol als offenen Schwingkreis durch Übertragung des LC-Modells erklären.', 'Zeitliche Strom-/Spannungsverteilungen mit elektrischen/magnetischen Nahfeldlinien verbinden.'], 'Die Modellübertragung vom geschlossenen zum offenen Kreis und die räumlich/zeitliche Feldbeschreibung sind eigenständige physikalische Leistungen. Ein Dipolwortbild genügt nicht für beide Feldarten.', ['Qualitative Orts-/Zeitverteilungen und Feldliniendarstellung'], ['Offener Schwingkreis versus zeitliche Nahfeld- und Strom-/Spannungsverteilungen'], 'Felder im Nahbereich des Dipols')
d(164,P,B, ['Empfangsmöglichkeiten von Stab- und Ringantennen mit Abstrahlcharakteristik, Fernfeldstruktur und Resonanz beurteilen.', 'Die kleinste optimale Dipolempfangslänge frequenzabhängig berechnen.'], 'Richtungs-/Feldkopplung bei zwei Antennentypen und numerische Dipollängenwahl sind unterschiedliche Nachweise. Die reine Längenrechnung erfasst das Ringantennenmodell nicht.', ['Wellenlänge-Frequenz- und Dipollängenrelation'], ['Empfangscharakteristik Stab/Ring versus resonante Dipollängenrechnung'], 'Stabantennen) und Spulen (Ringantennen')
d(165,P,B, ['Dipolstrahlung interferenzbasiert untersuchen und ihre Wellenlänge experimentell bestimmen.', 'Konstruktive/destruktive und stehende elektromagnetische Wellen durch Superposition erklären.', 'Die Ausbreitungsgeschwindigkeit im Medium quantitativ bestimmen.'], 'Interferenzmessung, stehende Welle und Materieabhängigkeit der Ausbreitung sind getrennte Inhalte. Die mechanische Analogie ordnet diese, ersetzt aber keinen der Nachweise.', ['Weglängen-/Knotenbeziehungen und Geschwindigkeits-Wellenlängen-Frequenzrechnung'], ['Interferenz/Wellenlängenmessung versus stehende Welle versus Mediumsgeschwindigkeit'], 'in Abhängigkeit von der durchdrungenen Materie')
d(166,P,B, ['Licht durch den Vergleich mehrerer Wellenexperimente als elektromagnetische Welle identifizieren.', 'Risiken und Schutzmaßnahmen bei nichtionisierenden Radio-, Mikrowellen- und Lichtanwendungen begründet bewerten.'], 'Der empirische Wellenidentitätsnachweis und die strahlungsbezogene Sicherheitsbewertung sind unabhängig assessierbar. Die genannten Technologien erweitern den zweiten Scope; eine biologische Wirkungslehre wird nicht ausdrücklich ausformuliert.', ['Qualitativer Vergleich von Beugung/Interferenz/Brechung/Reflexion/Polarisation'], ['Wellenidentifikation über fünf Phänomene versus spektrums-/technologiebezogene Sicherheitsbewertung'], 'Beugung, Interferenz, Brechung, Reflexion und Polarisation')
d(167,P,B, ['Lichtwellenlänge aus Doppelspalt- oder Gitterdaten bestimmen.', 'Den Einfluss der Spaltanzahl auf die Intensitätsverteilung qualitativ beurteilen.', 'Maxima-/Minimawinkel verschiedener Ordnung am Gitter berechnen.'], 'Wellenlängeninversion, Intensitätsschärfe durch Mehrfachspalte und Winkel-Ordnungsbedingungen sind getrennt nachweisbar. Es wäre unzutreffend, dieses ganze Optikpaket aus einer einzigen Winkelformel als atomar zu erklären.', ['Trigonometrische Wegdifferenz-/Gitterbeziehungen und Ordnungswinkel'], ['Wellenlängenbestimmung versus Mehrspaltintensität versus Extremwinkelbedingungen'], 'Anzahl der durchleuchteten Spalte')
d(168,P,B, ['Gasentladungs- und Glühlicht mit einem optischen Gitter spektral zerlegen und Spektren vergleichen.', 'Spektrallinien und sichtbare Spektralfarbenbereiche experimentell als Wellenlängen bestimmen.'], 'Methoden-/Quellentypvergleich und quantitative Spektralauswertung sind eigene Leistungsanteile. Die genannte Kohärenzvoraussetzung für die verschiedenartigen Lichtquellen verlangt fachliche Präzisierung im Scope.', ['Gitterwinkel-Wellenlängenrechnung und Spektraldiagramme'], ['Spektren-/Quellentypvergleich versus Linien-/Farbbereichsmessung; Kohärenzvoraussetzung präzisieren'], 'unter der Voraussetzung kohärenter Lichtquellen')
d(169,P,B, ['Gitterkonstanten periodischer Strukturen durch eigene Lichtinterferenzversuche bestimmen.', 'Technische Anwendungsmöglichkeiten der untersuchten Strukturen bewerten.'], 'Die eigenständige Gittermessung und die technische Eignungsbewertung können getrennt gelingen. Der Text benennt nicht, welche gemessene Eigenschaft eine konkrete Anwendung trägt.', ['Interferenzgeometrie nach Gitterkonstante auflösen'], ['Gitterkonstantenmessung versus anwendungsspezifische Eignungsbewertung'], 'optische Beugungsgitter, optische Datenträger')
d(170,S,C,[], 'T13 Quanten- und Atomphysik enthält acht breite Ziele von Doppelspalt-Quantenobjekten bis Röntgenstrahlung. Der leere Beschreibungstext ist ein Themenbündel und kein eigener Quantenkompetenznachweis.', [], [], '')
d(171,P,B, ['Klassische Teilchen, klassische Wellen und Quantenobjekte am Doppelspalt vergleichen.', 'Einzelmessungswahrscheinlichkeiten aus Interferenzmustern qualitativ vorhersagen.', 'Quantenwellenlängen aus Doppelspaltbeugung/-interferenz berechnen.'], 'Modellvergleich, probabilistische Einzelmessungsdeutung und quantitative Wellenlänge sind getrennte physikalische Inhalte. Die Wahrscheinlichkeit ist hier eine Quantenprognose, kein freistehendes Statistikziel.', ['Interferenzgeometrie und qualitative Wahrscheinlichkeitsdeutung'], ['Klassisch/quantischer Modellvergleich versus Einzelmessungswahrscheinlichkeit versus Wellenlänge'], 'qualitative Wahrscheinlichkeitsvorhersagen')
d(172,P,B, ['Interferenzfähigkeit mit Welcher-Weg-Information und Messvorgang begründen.', 'Ort-Impuls-Unbestimmtheit zur Kritik klassischer Quantenmodelle einsetzen.', 'Den damit verbundenen Wandel des physikalischen Weltbilds erklären.'], 'Komplementarität und Heisenbergsche Unbestimmtheit sind eigene physikalische Prinzipien. Der zusätzliche Weltbildauftrag ist eine epistemische Zusammenfassung, aber kein Ersatz für einen der beiden Fachnachweise.', ['Qualitative Komplementaritäts- und Ort-Impuls-Relationsdeutung'], ['Welcher-Weg-Komplementarität versus Ort-Impuls-Unbestimmtheit versus Weltbilddeutung'], 'Unbestimmtheitsrelation von Heisenberg')
d(173,P,B, ['Elektronenbeugungsmuster mit Bragg-Reflexion auswerten und die de-Broglie-Beziehung gewinnen.', 'Technische Herausforderungen der Wellenlängenbestimmung verschiedener Quantenobjekte diskutieren.'], 'Die Elektronen-Auswertung und der Transfer auf beispielsweise Fullerene benötigen verschiedene Evidenz. Die technischen Messgrenzen folgen nicht schon aus einem einzelnen Bragg-Winkel.', ['Bragg-Geometrie und de-Broglie-Relation'], ['Elektronenbeugungs-/de-Broglie-Auswertung versus Messgrenzen anderer Quantenobjekte'], 'z. B. Fullerene')
d(174,P,B, ['Austrittsarbeit, Grenzfrequenz und Planck-Konstante aus quantitativen Fotoeffektdaten bestimmen.', 'Strahlung-Materie-Wechselwirkung durch quantisierte Energie- und Impulsübertragung erklären.'], 'Die Parameter einer Fotoeffektgeraden bilden einen gemeinsamen Datenauswertungsauftrag. Die zusätzlich verlangte allgemeine Energie- und Impulsübertragung bei Wechselwirkungen erweitert ihn um eine eigenständige Erklärung.', ['Lineare Frequenz-Energie-Auswertung mit Steigung und Achsenschnitt'], ['Fotoeffektparameter aus Daten versus quantisierte Energie-/Impulswechselwirkung'], 'quantisierten Energie‑ und Impulsübertragung')
d(175,P,B, ['Elektronenstoßanregung und Photonenabsorption bei Atomen experimentell unterscheiden.', 'Strahlungsfrequenzen/-wellenlängen aus atomaren Energieniveaudifferenzen bestimmen.', 'Wasserstoffspektren mit der empirischen Serienformel einordnen.'], 'Anregungsmechanismen, Übergangsenergierechnung und spezielle Wasserstoffserien sind eigenständige Inhalte. Das Energieniveauschema ordnet sie, kann aber keinen vollständigen Nachweis durch eine einzige Übergangsrechnung liefern.', ['Energie-Frequenz-/Wellenlängenrelation und Wasserstoffserienformel'], ['Anregungsmechanismus versus Übergangsenergiebilanz versus Wasserstoffserie'], 'empirisch gewonnene Serienformel')
d(176,P,B, ['Gebundene Quantenzustände mit Ψ und abschnittweise konstantem Potenzial modellieren.', 'Diskrete Eigenzustände des eindimensionalen unendlichen Potenzialtopfs mit Randbedingungen aus der Schrödingergleichung bestimmen.', 'Ψ und |Ψ|² darstellen und Bereichs-Aufenthaltswahrscheinlichkeiten deuten.'], 'Potenzialmodellwahl, Eigenzustandslösung und Wahrscheinlichkeitsdeutung sind getrennte physikalische Inhalte. Differenzial- und Integralrechnung sind Werkzeuge der Quantenmodellierung; aus diesem Blatt folgt keine Freigabe eines abstrakten Mathematikprerequisites.', ['Differenzial-/Integralrechnung, Randbedingungen, Eigenzustandsfunktionen und Wahrscheinlichkeitsgraphen'], ['Potenzialmodell versus Schrödinger-Eigenlösung versus Born-/Bereichswahrscheinlichkeit'], 'eindimensionalen Potenzialtopfs mit unendlich hohen Wänden')
d(177,P,B, ['Potenzialtopfmodelle durch Vergleich berechneter Energien mit Absorptions-/Emissionsspektren auf Gültigkeit prüfen.', 'Elektronenkonfigurationen gebundener Mehrelektronensysteme mit dem Pauli-Prinzip ermitteln.'], 'Spektraler Modellvergleich und Pauli-Besetzungsregeln sind verschiedene physikalische Kompetenzen. Eine korrekt erkannte Potenzialtopfgrenze weist keine Mehrelektronenkonfiguration nach.', ['Vergleich theoretischer und experimenteller Energiewerte'], ['Modellvalidität aus Spektren versus Pauli-/Mehrelektronenkonfiguration'], 'Pauli-Prinzip')
d(178,I,B, ['Röntgenerzeugung und kontinuierliche/charakteristische Spektren mit Spannung und Anodenmaterial erklären.', 'Materialien aus Spektren sowie Strukturen/Wellenlängen mittels Bragg-Reflexion bestimmen.', 'Medizintechnischen Röntgeneinsatz unter gesundheitlichen Kriterien bewerten.'], 'Das Blatt verbindet Quellenphysik, Spektroskopie/Strukturanalyse und einen ausdrücklich gesundheitlichen Bewertungsauftrag. Die medizinische Abwägung benötigt zusätzliche biologische/medizinische Evidenz neben Spektralrechnung.', ['Röntgen-Energie-/Wellenlängenrelationen und Bragg-Geometrie'], ['Erzeugungs-/Spektrenmodell versus Material-/Bragg-Analyse versus gesundheitliche Bewertung'], 'unter gesundheitlichen Gesichtspunkten')
d(179,S,C,[], 'T13 Kernphysik enthält sieben verschiedene Ziele von Beschleunigerstreuung bis biologischem Strahlenschutz. Der Cluster beschreibt einen Themenbereich und keine einzelne nuklearphysikalische Leistung.', [], [], '')
d(180,P,N, ['Die für eine subatomare oder subnukleare Streuauflösung nötige Teilchenbeschleunigerenergie aus Masse, Impuls und Gesamtenergie bestimmen.'], 'Die klassischen und relativistischen Größenbeziehungen dienen einem bestimmten physikalischen Auflösungs-/Streuauftrag. Die Rutherford-Streuung ist ein benannter Anwendungsfall dieses Zusammenhangs.', ['Klassische/relativistische Masse-Impuls-Energie-Beziehungen'], [], 'insbesondere Rutherford-Streuung')
d(181,P,B, ['Kernaufbau und Stabilität mit starker Kernkraft und Bindungsenergie pro Nukleon erklären.', 'Energiefreisetzung durch Spaltung und Fusion aus Bindungsenergien erklären.'], 'Stabilitätsbegründung und Reaktionsenergien bilden unterschiedliche Kernphysiknachweise. Spaltung und Fusion ergänzen verschiedene Reaktionssituationen zum Bindungsmodell.', ['Massendefekt-/Bindungsenergieberechnung pro Nukleon'], ['Kernstruktur/Stabilität versus Spaltungs- und Fusionsenergiebilanz'], 'Kernspaltung bzw. Kernfusion')
d(182,P,B, ['α-Zerfall mit Potenzialtopf/Tunneleffekt und β-Zerfälle mit Quarkumwandlung erklären.', 'γ-Strahlung als Kernübergang gegenüber den Teilchenzerfällen abgrenzen.', 'Strahlungsarten und Teilchenenergien durch geeignete Experimente unterscheiden/messen.'], 'Mehrere mikroskopische Zerfallsmechanismen sowie Nachweis-/Energiemessung sind unabhängige Inhalte. Der Potenzialtopf erklärt nicht in identischer Weise Tunnelprozess, Quarkumwandlung und γ-Übergang.', ['Quantitative Strahlungsenergieauswertung nicht festgelegt'], ['α-Tunneln versus β-Quarkumwandlung versus γ-Übergang versus experimenteller Nachweis'], 'Umwandlung von Quarks')
d(183,P,N, ['Eine Kernreaktion durch Reaktionsgleichung und Massendefekt als exotherm oder endotherm klassifizieren.'], 'Gleichung, Massensaldo und Energiezeichen gehören zu einer gemeinsamen Reaktionsbilanz. Das Berechnen ist die Evidenz für die physikalische Reaktionsklassifikation.', ['Massensaldo und Masse-Energie-Relation'], [], 'nach exothermen und endothermen Reaktionen')
d(184,P,B, ['α- und β-Energiespektren mit Erhaltungssätzen interpretieren.', 'Nachfolgende γ-Emission angeregter Tochterkerne mit diskreten Kernenergien verknüpfen.'], 'Diskrete α- und kontinuierliche β-Spektren sowie nachfolgende Kernübergänge sind getrennte physikalische Inhalte. Die Kernniveau-Rechnung erfordert einen eigenen Nachweis neben der Spektreninterpretation.', ['Erhaltungsbilanzen und diskrete Kernenergiedifferenzen'], ['α-/β-Spektreninterpretation versus Tochterkern-/γ-Niveaubestimmung'], 'angeregten Tochterkernen')
d(185,P,B, ['Exponentiell abklingende physikalische Messreihen grafisch auswerten und charakteristische Abklinggrößen bestimmen.', 'Technische Einsatzmöglichkeiten aus diesen Abklinggrößen beurteilen.'], 'Die Datenauswertung und technische Eignungsbewertung sind eigenständig. Der Text nennt weder den konkreten Abklingvorgang noch eine Anwendung, so dass das exponentielle Modell den vollständigen Inhalt nicht begrenzt.', ['Exponentialfunktion zur Basis e und grafische Parameterbestimmung'], ['Abklingparameter versus technische Eignung; Prozess-/Anwendungsscope offen'], 'Exponentialfunktion mit der Basis e')
d(186,I,B, ['Ionisierende Strahlungswirkung auf Gewebe durch Wechselwirkung mit Materie erklären.', 'Dosis-/Aktivitätsmessgeräte und Energie-/Äquivalentdosis zur Wirkungseinordnung erklären.', 'Nuklearmedizinische Verfahren hinsichtlich Nutzen/Risiko bewerten und passende Schutzmaßnahmen wählen.'], 'Der explizite Gewebe- und Nuklearmedizinanteil verlangt biologische/medizinische Bewertung neben der Dosimetriephysik. Detektoren, Dosisbegriffe und medizinische Nutzenabwägung sind unterschiedliche Nachweise.', ['Dosisgrößen und gegebenenfalls Aktivitäts-/Energiebeziehungen'], ['Materiewechselwirkung versus Detektor/Dosimetrie versus biologisch-medizinische Nutzenabwägung und Schutz'], 'Risiken und den Nutzen von Behandlungsmethoden')
d(187,S,C,[], 'ABUAdditum13 Mechanische Schwingungen ordnet fünf Ziele zu Kenngrößen, Zeitmodellen, Wert-/Zeitbestimmung, Rückstellkraft und Energie. Der Additumtitel ist ein wörtliches Profilsegment ohne eigene Zielbeschreibung.', [], [], '')
d(188,P,N, ['Amplitude, Periodendauer und Frequenz einer harmonischen mechanischen Schwingung aus experimentellen Daten bestimmen.'], 'Die drei Kenngrößen charakterisieren dieselbe beobachtete Schwingung. Im Additumtext fehlt der umfassende selbständige Planungsauftrag und der Inhalt bleibt die konkrete Datenauswertung.', ['Elongations-/Zeitdaten und Frequenz-Periodendauer-Beziehung'], [], 'aus experimentell gewonnen Daten')
d(189,P,B, ['Orts-, Geschwindigkeits- und Beschleunigungsverläufe einer harmonischen Schwingung mit Anfangsbedingungen trigonometrisch beschreiben.', 'Diese Verläufe in Zeiger- und Liniendiagrammen darstellen.'], 'Das Additum fordert ausdrücklich drei phasenbezogene Größenfunktionen und zwei Darstellungsarten. Diese lassen sich getrennt korrekt oder falsch bearbeiten und sind keine automatisch einzelne atomare Kompetenz.', ['Trigonometrische Funktionen, Zeiger- und Liniendiagramme'], ['Drei kinematische Schwingungsfunktionen versus Zeiger-/Liniendarstellung'], 'Zeiger‑ und Liniendiagramme')
d(190,P,B, ['Aus einem Zeitpunkt Ort, Geschwindigkeit und Beschleunigung einer harmonischen Schwingung grafisch/rechnerisch bestimmen.', 'Alle passenden Zeitpunkte zu vorgegebener Auslenkung, Geschwindigkeit oder Beschleunigung bestimmen.'], 'Vorwärtsauswertung und inverse periodische Zeitbestimmung stellen verschiedene Anforderungen. Besonders mehrere mögliche Zeitlösungen werden durch die bloße Berechnung eines Funktionswerts nicht nachgewiesen.', ['Trigonometrische Funktionswerte und inverse periodische Lösung; Graphauswertung'], ['Vorwärtswertbestimmung versus inverse mehrdeutige Zeitbestimmung für x/v/a'], 'die Zeiten, an denen')
d(191,P,B, ['Harmonizität aus linearer Rückstellkraft begründen und Richtgröße bestimmen.', 'Richtgröße mit Eigenfrequenz, Periodendauer, Energie, Amplitude und Masse verknüpfen.'], 'Auch im ABUAdditum13-Text stehen Harmonizitätskriterium und umfassende Größenrelationen nebeneinander. Federschwere-, Faden- und Flüssigkeitspendel verlangen jeweils eine begründete Rückstellkraftwahl.', ['Lineares Kraftgesetz und Schwingungsrelationen'], ['Rückstellkraft/Harmonizität versus Zeit- und Energierelationen verschiedener Pendel'], 'Federschwerependel, Fadenpendel, Flüssigkeitspendel')
d(192,P,B, ['Schwingungsenergien über Zeit und Elongation darstellen und mit Energieerhaltung quantitativ bilanzieren.', 'Dämpfung qualitativ erklären.'], 'Das Additum-Blatt verknüpft ideale Energiekurven mit dissipativem Verhalten. Energieerhaltung in einem idealen Pendel beweist die zusätzliche Dämpfungserklärung nicht.', ['Zeit-/Elongations-Energiegraphen und Energiebilanz'], ['Ideale Energiedarstellung und -bilanz versus dissipative Dämpfung'], 'Schwingungsdämpfern')
d(193,S,C,[], 'ABUAdditum13 Wellen enthält vier konkrete Ziele zu Wellenkenngrößen, Beugung, Kreiswelleninterferenz und Laserwellenlänge. Es ist ein Themencluster ohne eigene Wellennachweisleistung.', [], [], '')
d(194,P,N, ['Mechanische Wellen in Wellenwanne oder Wellenmaschine charakterisieren und Wellenlänge, Frequenz und Ausbreitungsgeschwindigkeit ermitteln.'], 'Entstehung/Ausbreitung und Kenngrößen sind hier auf die Charakterisierung desselben Versuchsphänomens gerichtet. Die zwei Geräte sind alternative Zugänge, keine voneinander unabhängigen Inhaltsziele.', ['Wellenlängen-, Zeit- und Geschwindigkeitsrelation'], [], 'mittels einer Wellenwanne und Wellenmaschine')
d(195,P,N, ['Die Beugung einer Wellenfront mit Huygens und Superposition erklären.'], 'Zwei Modellprinzipien dienen einem einzigen eng benannten Phänomen. Es werden weder Interferenzorte noch ein quantitatives Beugungsminimum als zusätzliche Leistung verlangt.', ['Qualitative Elementarwellen-/Superpositionskonstruktion'], [], "Huygens'sche Prinzip sowie das Superpositionsprinzip")
d(196,P,N, ['Interferenzmaxima und -minima zweier Kreiswellen aus konstruierten Überlagerungsamplituden bestimmen.'], 'Die Konstruktion liefert die Entscheidung über ein einziges physikalisches Interferenzmuster. Sie ist keine eigenständige allgemeine Geometriekompetenz.', ['Geometrische/amplitudenbezogene Wellenüberlagerung'], [], 'Konstruktion der Überlagerungsamplitude zweier Kreiswellen')
d(197,P,B, ['Licht als elektromagnetische Welle identifizieren und Gitterinterferenz mit dem Wellenmodell erklären.', 'Laserwellenlänge experimentell aus Gitterinterferenz bestimmen.'], 'Die elektromagnetische Identifikation erfordert eigene Evidenz über eine Wellenlängenmessung hinaus. Eine gemessene Gitterinterferenz bestätigt Wellenverhalten, beweist allein aber keine elektromagnetische Zuordnung.', ['Gittergeometrie zur Wellenlängenbestimmung'], ['Elektromagnetische Identifikation versus Wellenmodell/Gitterwellenlängenmessung'], 'Licht als elektromagnetische Welle identifizieren')
d(198,S,C,[], 'ABUAdditum13 Kernphysik bündelt fünf Ziele zu Kernenergie, Zerfall, Detektion und Schutz-/Dosisrechnung. Der Knoten ist ein fachlicher Inhaltscontainer, kein eigener Prüfungs- oder Memorierungsauftrag.', [], [], '')
d(199,I,B, ['Kernprozesse anhand von Kern-/Isotopenmodellen erklären und ihre Energieumwandlung berechnen.', 'Friedliche Kernenergienutzung nach Nutzen/Risiko sowie wirtschaftlichen, ökologischen und Entsorgungskriterien bewerten.'], 'Die Beschreibung verlangt ausdrücklich wirtschaftliche und ökologische Urteile zusätzlich zur Kernphysik. Eine Reaktionsenergierechnung deckt den Umgang mit Abfällen und gesellschaftlichen Nutzenabwägungen nicht ab.', ['Kernprozess-Energieberechnung'], ['Kernmodell/Energierechnung versus wirtschaftlich-ökologische Risiko-/Entsorgungsbewertung'], 'wirtschaftlichen und ökologischen Gesichtspunkte')
d(200,P,N, ['Natürliche Radioaktivität als Nuklidzerfall durch passende Kernreaktionsgleichungen darstellen.'], 'Zerfallserklärung und Reaktionsdarstellung gehören zum selben physikalischen Umwandlungsnachweis. Es ist weder eine Zerfallsgesetzrechnung noch allgemeine Chemiegleichungskompetenz gefordert.', ['Bilanzierung von Kernladungs- und Nukleonenzahlen'], [], 'Zerfall eines instabilen Nuklids')
d(201,P,B, ['Radioaktive Strahlungsarten anhand ihrer physikalischen Eigenschaften unterscheiden.', 'Die prinzipielle Funktion radioaktiver Nachweisgeräte aus diesen Eigenschaften erklären.'], 'Die Eigenschaften unterschiedlicher Strahlungsarten und die Wirkmechanismen von Detektoren sind eigene Inhalte. Ohne benanntes Gerät bleibt unklar, welche Eigenschaft welcher Nachweisfunktion zugrunde liegt.', [], ['Strahlungsarteneigenschaften versus Detektorprinzipien; Gerätescope offen'], 'Nachweisgeräten für radioaktive Strahlung')
d(202,I,B, ['Langzeitverläufe natürlicher/künstlicher Radioaktivität mit dem Zerfallsgesetz berechnen und Folgen für Mensch/Umwelt abschätzen.', 'Mit Absorptions- und Abstandsgesetz konkrete Strahlenschutzmaßnahmen ableiten.'], 'Zeitliche Abnahme, biologische/ökologische Langzeitfolge sowie Abschirmung und Distanz sind verschiedene Inhalte. Die mathematischen Gesetze liefern physikalische Expositionswerte, ersetzen keine Wirkungsbegründung.', ['Radioaktives Zerfallsgesetz, Absorptionsgesetz und Abstandsgesetz'], ['Zeitlicher Zerfall versus biologisch-ökologische Langzeitwirkung versus Abschirmung/Distanz'], 'Langzeitauswirkungen von natürlicher und künstlicher Radioaktivität')
d(203,P,B, ['Aktivität und Halbwertszeit radioaktiver Substanzen berechnen.', 'Energie- und Äquivalentdosis zur Gefahrenabschätzung berechnen und fach-/adressatengerecht darstellen.'], 'Zeitliche Emissionsrate und Halbwertszeit sind andere Größen als absorbierte und biologisch gewichtete Dosis. Der Text fordert die ganze Größenfamilie und eine Gefahrenpräsentation ohne begrenztes Expositionsszenario.', ['Aktivitäts-/Zerfallsrelationen und Dosis-/Gewichtungsrechnung'], ['Aktivität/Halbwertszeit versus Energie-/Äquivalentdosis; Expositionsscope offen'], 'Aktivität, Halbwertszeit, Energie‑ und Äquivalentdosis')
d(204,S,Y,[], 'Jahrgang 13 platziert drei Aspekte13-, vier T13- und drei ABUAdditum13-Lernbereiche. Es ist ausdrücklich eine Programmgruppierung unterschiedlicher wörtlicher Profile ohne eigenen fachlichen Beschreibungstext.', [], [], '')
d(205,S,Y,[], 'Der Fachroot ist ein leer beschriebener Landschafts-/Programmtitel mit dem Orientierungsanker und vier Jahrgängen als Kindern. Er ist keine globale Physikbeherrschung; sein vorhandenes requires ist nur erfasst, nicht als didaktisch nötig freigegeben.', [], [], '')

source_bytes = SOURCE.read_bytes()
source_hash = hashlib.sha256(source_bytes).hexdigest()
agents_hash = hashlib.sha256(pathlib.Path('AGENTS.md').read_bytes()).hexdigest()
assert source_hash == EXPECTED_SOURCE_HASH, 'Physics changed after personal read'
assert agents_hash == EXPECTED_AGENTS_HASH, 'AGENTS changed after personal read'
landscape = json.loads(source_bytes)
goals = landscape['goals']
assert len(goals) == 206
assert [r['index'] for r in rows] == list(range(206))
by_id = {g['id']: g for g in goals}
parents = {g['id']: [] for g in goals}
for parent in goals:
    for child_id in parent['contains']:
        assert child_id in by_id
        parents[child_id].append(parent)

def hash_utf8(value):
    return hashlib.sha256(value.encode('utf-8')).hexdigest()

def hash_canonical(value):
    return hash_utf8(json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(',', ':')))

allowed_subjects = {'Physics', 'Math', 'interdisciplinary', 'structural', 'unresolved'}
allowed_roles = {'assessable_narrow_atomic_candidate', 'broad_outcome_requires_split', 'program', 'cluster', 'competency_axis', 'orientation', 'memory', 'admin_content_fragment'}
entries = []
for row in rows:
    index = row['index']
    goal = goals[index]
    description = goal['description']
    assert row['actualSubject'] in allowed_subjects
    assert row['semanticRole'] in allowed_roles
    assert row['readAnchor'] in description
    assert bool(row['granularityGapNames']) == (row['semanticRole'] == B)
    assert (row['actualSubject'] == S) == (row['semanticRole'] in {Y,C})
    if row['semanticRole'] == N:
        assert len(row['assessmentUnits']) == 1
    parent_bindings = [{
        'goalId': p['id'], 'title': p['title'],
        'titleSha256': hash_utf8(p['title']),
        'contains': p['contains'],
        'containsCanonicalJsonSha256': hash_canonical(p['contains']),
        'descriptionSha256': hash_utf8(p['description']),
    } for p in parents[goal['id']]]
    ancestor_titles = []
    queue = list(parents[goal['id']])
    seen = set()
    while queue:
        p = queue.pop(0)
        if p['id'] in seen:
            continue
        seen.add(p['id'])
        ancestor_titles.append(p['title'])
        queue.extend(parents[p['id']])
    child_bindings = [{
        'goalId': child_id,
        'title': by_id[child_id]['title'],
        'descriptionSha256': hash_utf8(by_id[child_id]['description']),
    } for child_id in goal['contains']]
    gaps = [{'gapId': f'BY-FOS-PHYS-{index:03d}-G{n+1}', 'name': label,
             'status': 'author_named_open', 'approvedSplit': False}
            for n, label in enumerate(row['granularityGapNames'])]
    entries.append({
        'index': index,
        'goalId': goal['id'],
        'title': goal['title'],
        'description': description,
        'sourceFile': str(SOURCE),
        'sourceFileSha256': source_hash,
        'titleSha256': hash_utf8(goal['title']),
        'descriptionSha256': hash_utf8(description),
        'goalCanonicalJsonSha256': hash_canonical(goal),
        'actualSubject': row['actualSubject'],
        'semanticRole': row['semanticRole'],
        'assessmentUnits': row['assessmentUnits'],
        'reason': row['reason'],
        'mathematicalRepresentationMethods': row['mathematicalRepresentationMethods'],
        'mathematicalMethodsAreApprovedPrerequisites': False,
        'granularityGaps': gaps,
        'technicalLeaf': not bool(goal['contains']),
        'actualParentScopes': parent_bindings,
        'actualAncestorTitles': ancestor_titles,
        'actualContains': goal['contains'],
        'actualContainsTargets': child_bindings,
        'existingRequiresObservedOnly': goal['requires'],
        'authorAgentIdentity': AUTHOR,
        'decisionStatus': 'inert_author_draft_unreviewed',
        'sourceCoverageStatus': 'local_goal_text_and_tree_only_per_goal_official_source_unresolved',
        'readWitness': {
            'readerAgentIdentity': AUTHOR,
            'readMode': 'personal_full_description_and_actual_parent_title_contains_scopes',
            'fullDescriptionRead': True,
            'fullDescriptionCharacterCount': len(description),
            'fullDescriptionSha256': hash_utf8(description),
            'fullDescriptionExactText': description,
            'handSelectedContentAnchor': row['readAnchor'],
            'anchorSha256': hash_utf8(row['readAnchor']),
            'actualParentScopesRead': True,
            'emptyDescriptionWitness': row['reason'] if not description else None,
            'individualDecisionWitness': row['reason'],
        },
        'approvals': {
            'nativeM7Approved': False,
            'semanticAtomicityApproved': False,
            'newPrerequisiteEdgesApproved': False,
            'activeGraphEditApproved': False,
            'independentReviewCompleted': False,
        },
    })

document = {
    'schemaVersion': 'by-fos-semantic-author-classifications-v1',
    'artifactStatus': 'inert_author_draft_unreviewed',
    'createdAt': datetime.datetime.now(datetime.timezone.utc).isoformat(),
    'authorAgentIdentity': AUTHOR,
    'authorRole': 'AUTHOR_NOT_INDEPENDENT_REVIEWER',
    'sourceFile': str(SOURCE),
    'sourceFileSha256': source_hash,
    'agentsFile': 'AGENTS.md',
    'agentsFileSha256': agents_hash,
    'goalCount': len(entries),
    'technicalLeafCount': sum(e['technicalLeaf'] for e in entries),
    'indexConvention': 'zero_based_source_goals_array_order',
    'hashConventions': {
        'file': 'sha256_of_exact_file_bytes',
        'description': 'sha256_of_exact_description_string_encoded_utf8_without_normalization',
        'canonicalJson': 'sha256_of_python_json_ensure_ascii_false_sort_keys_true_separators_comma_colon_encoded_utf8',
    },
    'judgmentMethod': 'Each complete goal description and actual parent/contains scope was personally read before individual drafting. Classification is not inferred from filename, leafness or keywords. Repeated descriptions were read at each index and individually scoped.',
    'relevantInstructionsRead': ['AGENTS.md §§2.1–2.3: goals/programs/clusters/axes separate', 'AGENTS.md §4: orientation is motivation without subject-matter grading', 'AGENTS.md §7 and §7.1: exact single content goal, leafness does not imply atomicity, some integrated calculation/interpretation may remain one goal'],
    'profileLabelsObservedLiterally': ['Ph10', 'Physik 11 (ABU)', 'Physik 12 (ABU)', 'Physik 11 (T)', 'Physik 12 (T)', 'Physik 13 (T)', 'Aspekte der Physik 12 (erweiterndes Wahlplichtfach G,S,W, GH, IW)', 'Aspekte der Physik 13 (erweiterndes Wahlplichtfach G,S,W, GH, IW)', 'Physik Additum 13 (ABU)'],
    'scopeLimitations': [
        'Profile labels are recorded literally; no legal expansion or normative equivalence is claimed.',
        'Local text and graph context support author classification only; per-goal official sourceRefs/URLs are not supplied by this file.',
        'Mathematical methods are represented separately from physical targets; none of the listed methods authorizes mathematics mastery requirements or prerequisite edges.',
        'Narrow candidate means an author proposal, not approved semantic atomicity or native M7 acceptance.',
        'Granularity gaps name content divisions for subsequent review; no split or active graph change is performed.',
    ],
    'countsByActualSubject': dict(Counter(e['actualSubject'] for e in entries)),
    'countsBySemanticRole': dict(Counter(e['semanticRole'] for e in entries)),
    'entries': entries,
}
assert source_hash == hashlib.sha256(SOURCE.read_bytes()).hexdigest()
assert agents_hash == hashlib.sha256(pathlib.Path('AGENTS.md').read_bytes()).hexdigest()
assert not OUT.exists(), 'Exclusive new output must not overwrite any prior artifact'
OUT.write_text(json.dumps(document, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(json.dumps({'path': str(OUT), 'fileSha256': hashlib.sha256(OUT.read_bytes()).hexdigest(),
                  'goalCount': document['goalCount'], 'technicalLeafCount': document['technicalLeafCount'],
                  'countsByActualSubject': document['countsByActualSubject'],
                  'countsBySemanticRole': document['countsBySemanticRole']}, ensure_ascii=False))
